--SECTION - New Ui
do -- Main Ui
	local Minecrafia = 1 --[[Drawing.new("Font", "Minecraftia")
	Minecrafia.Data = crypt.base64.decode(
		""
	)]]

	local Monolith = {}
	getgenv().Monolith = Monolith
	--

	local S, R = pcall(function()
		Monolith = getgenv().Monolith

		Monolith.Shared = { Menu = false, User = "wireless", Ping = 77, Fps = 77 }
		Monolith.Connections = {}
		Monolith.MousePosition = Vector2.new()
		Monolith.ScreenSize = Vector2.new(1920, 1080)
		Monolith.ScreenSizeFix = Vector2.new(1920, 1080) -- // Fix for Menu Image rendering breaking if the resolution isn't an even number

		local UserInputService = game:GetService("UserInputService")
		local Math = Monolith.Math

		-- // Connection stuff n shit
		do
			function Monolith:NewConnection(Name, Table, Type, Callback)
				local Connection = Type:Connect(Callback)
				--
				Table[Name] = Connection
				--
				return Connection
			end
			--
			function Monolith:CutConnection(Name, Table)
				local Connection = Table[Name]
				--
				if Connection then
					Connection:Disconnect()
					Table[Name] = nil
				end
			end
			--
			function Monolith:CutConnections(Table)
				for Index, _ in next, Table do
					Monolith:CutConnection(Index, Table)
				end
			end
		end

		-- // Initialize
		do
			Monolith:NewConnection(
				"Mouse Position",
				Monolith.Connections,
				game:GetService("Players").LocalPlayer:GetMouse().Move,
				function()
					Monolith.MousePosition = UserInputService:GetMouseLocation()
				end
			)
			--
			Monolith.ScreenSize = game:GetService("Workspace").CurrentCamera.ViewportSize
			Monolith.ScreenSizeHalf = Monolith.ScreenSize / 2
			Monolith.ScreenSizeFix =
				Vector2.new(Math:RoundToEven(Monolith.ScreenSize.X), Math:RoundToEven(Monolith.ScreenSize.Y))
		end
		--
		getgenv().Utilty = true
	end) -- Utility

	local S1, R1 = pcall(function()
		Monolith = getgenv().Monolith
		local NewVector3, NewVector2, Random, Round, Acos, Sin, Cos, Pi =
			Vector3.new, Vector2.new, math.random, math.round, math.acos, math.sin, math.cos, math.pi

		Monolith.Math = {}
		local Math = Monolith.Math

		do -- Math
			function Math:RoundToEven(Int)
				if Int % 2 == 1 then
					Int += 1
				end
				--
				return Int
			end
		end
		--
		getgenv().Math = true
	end) -- Math

	Monolith.LoadTick = tick()

	local Success, Response = pcall(function()
		Monolith = getgenv().Monolith
		local NewVector2, NewDrawing, Remove, Spawn, NewRGB, Insert, Delay, Format, Unpack, Round, Clamp, Floor, Wait, Wrap, Find, Gsub, Sub =
			Vector2.new,
			Drawing.new,
			table.remove,
			task.spawn,
			Color3.fromRGB,
			table.insert,
			task.delay,
			string.format,
			table.unpack,
			math.round,
			math.clamp,
			math.floor,
			task.wait,
			coroutine.wrap,
			table.find,
			string.gsub,
			string.sub
		--
		local RenderStepped = game:GetService("RunService").RenderStepped
		local UserInputService = game:GetService("UserInputService")
		local Camera = game:GetService("Workspace").CurrentCamera
		local Stats = game:GetService("Stats")

		local Font = 1--[[NewDrawing("Font", "Font")
		Font.Data = crypt.base64.decode(
			""
		)]]
		Monolith.Menu = {
			DrawingCount = 0,
			Connections = {},
			Drawings = {},
			Sections = {},
			Hidden = {},
			Flags = {},
			Tabs = {},
			Inputs = {
				Began = {},
				Changed = {},
				Ended = {},
			},
			Theme = {
				Colors = {
					Accent = NewRGB(255, 255, 255),
					A = NewRGB(0, 0, 0),
					B = NewRGB(12, 12, 12),
					C = NewRGB(14, 14, 14),
					D = NewRGB(21, 21, 21),
					E = NewRGB(92, 92, 92),
					F = NewRGB(35, 35, 35),
				},
				Text = {
					Size = 11,
					Font = Font,
					Color = NewRGB(255, 255, 255),
					Outline = NewRGB(0, 0, 0),
				},
			},
			Window = nil,
		}
		Monolith.Notes = {}

		local Menu = Monolith.Menu
		local Theme = Menu.Theme
		local Flags = Menu.Flags

		local Math = Monolith.Math

		Menu.__index = Menu
		Menu.Tabs.__index = Menu.Tabs
		Menu.Sections.__index = Menu.Sections

		-- // Menu Draw Functions
		LPH_NO_VIRTUALIZE(function()
			do
				function Menu:Size(xScale, xOffset, yScale, yOffset, Instance)
					local X, Y

					if Instance then
						X = xScale * Instance.Size.X + xOffset
						Y = yScale * Instance.Size.Y + yOffset
					else
						local Width = Monolith.ScreenSizeFix.X
						local Height = Monolith.ScreenSizeFix.Y
						X = xScale * Width + xOffset
						Y = yScale * Height + yOffset
					end

					return NewVector2(X, Y)
				end
				--
				function Menu:Position(xScale, xOffset, yScale, yOffset, Instance)
					local X, Y
					--
					if Instance then
						X = Instance.Position.X + xScale * Instance.Size.X + xOffset
						Y = Instance.Position.Y + yScale * Instance.Size.Y + yOffset
					else
						local vX, vY = Monolith.ScreenSizeFix.X, Monolith.ScreenSizeFix.Y
						X = xScale * vX + xOffset
						Y = yScale * vY + yOffset
					end
					--
					return NewVector2(X, Y)
				end
				--
				function Menu:Create(Type, Offset, Properties, Parent)
					local Type = Type or "Frame"
					local Offset = Offset or { NewVector2(0, 0) }
					local Properties = Properties or {}
					local Hidden = false
					local Instance = nil
					--
					if Type == "Frame" or Type == "frame" then
						local Frame = NewDrawing("Square")
						Frame.Visible = true
						Frame.Filled = true
						Frame.Thickness = 0
						Frame.Color = NewRGB(255, 255, 255)
						Frame.Size = NewVector2(100, 100)
						Frame.Position = NewVector2(0, 0)
						Frame.ZIndex = 1000
						Frame.Transparency = Monolith.Shared.Menu and 1 or 0
						--
						Instance = Frame
					elseif Type == "TextLabel" or Type == "textlabel" then
						local Text = NewDrawing("Text")
						Text.Font = 3
						Text.Visible = true
						Text.Outline = true
						Text.Center = false
						Text.Color = NewRGB(255, 255, 255)
						Text.ZIndex = 1000
						Text.Transparency = Monolith.Shared.Menu and 1 or 0
						--
						Instance = Text
					elseif Type == "Triangle" or Type == "triangle" then
						local Triangle = NewDrawing("Triangle")
						Triangle.Visible = true
						Triangle.Filled = true
						Triangle.Thickness = 0
						Triangle.Color = NewRGB(255, 255, 255)
						Triangle.ZIndex = 1000
						Triangle.Transparency = Monolith.Shared.Menu and 1 or 0
						--
						Instance = Triangle
					elseif Type == "Image" or Type == "image" then
						local Image = NewDrawing("Image")
						Image.Size = NewVector2(20, 20)
						Image.Position = NewVector2(0, 0)
						Image.Color = NewRGB(255, 255, 255)
						Image.Visible = true
						Image.ZIndex = 1000
						Image.Rounding = 0
						Image.Transparency = Monolith.Shared.Menu and 1 or 0
						--
						Instance = Image
					end
					--
					if Instance then
						for Index, Value in next, Properties do
							if Index == "Hidden" or Index == "hidden" then
								Hidden = Value
							else
								if Monolith.Shared.Menu then
									Instance[Index] = Value
								elseif Index ~= "Transparency" then
									Instance[Index] = Value
								end
							end
						end
						--
						if not Hidden then
							Menu.Drawings[#Menu.Drawings + 1] = { Instance, Offset, Properties["Transparency"] or 1 }
						else
							Menu.Hidden[#Menu.Hidden + 1] = { Instance, Offset, Properties["Transparency"] or 1 }
						end
						--
						if Parent then
							Parent[#Parent + 1] = Instance
						end
						--
						if not Properties.ZIndex then
							Menu.DrawingCount += 1
							Instance.ZIndex = Menu.DrawingCount
						end
						--
						return Instance
					end
				end
				--
				function Menu:UpdateOffset(Instance, Offset)
					for _, Value in next, Menu.Drawings do
						if Value[1] == Instance then
							Value[2] = Offset
							return
						end
					end
				end
				--
				function Menu:UpdateTransparency(Instance, Transparency)
					for _, Value in next, Menu.Drawings do
						if Value[1] == Instance then
							Value[3] = Transparency
							return
						end
					end
				end
				--
				function Menu:WrapText(Text, Size)
					local Max = (Size / 7) + 3
					--
					return Text:sub(0, Max)
				end
				--
				function Menu:Combine(Table1, Table2)
					local Combined = {}
					--
					for _, Value in next, Table1 do
						Insert(Combined, Value)
					end
					--
					for _, Value in next, Table2 do
						Insert(Combined, Value)
					end
					--
					return Combined
				end
				--
				function Menu:Remove(Instance, Hidden)
					local Table = Hidden and Menu.Hidden or Menu.Drawings
					--
					for Index, Value in next, Table do
						if Value[1] == Instance then
							Value[1] = nil
							Value[2] = nil
							--
							Remove(Table, Index)
							break
						end
					end
					--
					Instance:Remove()
				end
				--
				function Menu:MouseOverDrawing(Values, ValuesAdd)
					local X1 = (Values[1] or 0) + (ValuesAdd and ValuesAdd[1] or 0)
					local Y1 = (Values[2] or 0) + (ValuesAdd and ValuesAdd[2] or 0)
					local X2 = (Values[3] or 0) + (ValuesAdd and ValuesAdd[3] or 0)
					local Y2 = (Values[4] or 0) + (ValuesAdd and ValuesAdd[4] or 0)
					--
					local MouseX = Monolith.MousePosition.X
					local MouseY = Monolith.MousePosition.Y
					--
					return MouseX >= X1 and MouseX <= X2 and MouseY >= Y1 and MouseY <= Y2
				end
				--
				function Menu:GetTextBounds(Text, Size, Font)
					local TextLabel = Menu:Create("TextLabel", { NewVector2(0, 0) }, {
						Text = Text,
						Size = Size,
						Font = Font,
						Hidden = true,
					})
					--
					local TextBounds = TextLabel.TextBounds
					Menu:Remove(TextLabel, true)
					--
					return TextBounds
				end
				--
				function Menu:LoadImage(Instance, Name)
					if Images[Name .. ".png"] and Instance then
						Instance.Data = crypt.base64.decode(Images[Name .. ".png"])
					end
				end
				--
				function Menu:Lerp(Instance, To, Time)
					local CurrentTime = 0
					local CurrentIndex = {}
					local Connection
					--
					for Index, Value in next, To do
						CurrentIndex[Index] = Instance[Index]
					end
					--
					local Differences = {}
					for Index, Value in next, To do
						Differences[Index] = Value - CurrentIndex[Index]
					end
					--
					local function Lerp()
						for Index, Value in next, To do
							Instance[Index] = (Differences[Index] * CurrentTime / Time) + CurrentIndex[Index]
						end
					end
					--
					Connection = RenderStepped:Connect(LPH_NO_VIRTUALIZE(function(Delta)
						if CurrentTime < Time then
							CurrentTime = CurrentTime + Delta
							Lerp()
						else
							Connection:Disconnect()
						end
					end))
				end
			end
		end)()

		-- // Element Functions
		do
			function Menu:Window(Info)
				local Info = Info or {}
				local Name = Info.Name or Info.name or "Monolith.wtf"
				local Size = NewVector2(650, 400)
				local TabAmmount = Info.Tabs or 6
				--
				local Window = {
					Notes = {},
					Tabs = {},
					IsVisible = false,
					TabAmmount = TabAmmount,
					UiBind = Enum.KeyCode.Home,
