				)
				Menu:LoadImage(Line, "Line")
				--
				function Window:Unload()
					UserInputService.MouseIconEnabled = true
					--
					for _, Value in next, Menu.Hidden do
						Wrap(function()
							if Value[1] and Value[1].Remove then
								local Instance = Value[1]
								Value[1] = nil
								Value = nil
								--
								Instance:Remove()
							end
						end)()
					end
					--
					for _, Value in next, Menu.Drawings do
						Wrap(function()
							if Value[1] and Value[1].Remove then
								local Instance = Value[1]
								Value[2] = nil
								Value[1] = nil
								Value = nil
								--
								Instance:Remove()
							end
						end)()
					end
					--
					Monolith:CutConnections(Menu.Connections)
				end
				--
				function Window:GetConfig()
					local Config = {}
					--
					for Index, Value in next, Flags do
						if type(Value:Get()) == "table" and Value:Get().Transparency then
							local Hue, Sat, Val = Value:Get().Color:ToHSV()
							Config[Index] = { Color = { Hue, Sat, Val }, Transparency = Value:Get().Transparency }
						elseif Value.KeybindName then
							local Key, Mode = Value:Get(), Value.Mode
							Config[Index] = { Key = Key, Mode = Mode }
						elseif typeof(Value:Get()) == "Color3" then
							local Hue, Sat, Val = Value:Get():ToHSV()
							Config[Index] = { Color = { Hue, Sat, Val }, Transparency = Value.Current[4] or 1 }
						else
							Config[Index] = Value:Get()
						end
					end
					--
					return HttpService:JSONEncode(Config)
				end
				--
				function Window:LoadConfig(Config)
					local Config = HttpService:JSONDecode(Config)
					--
					for Index, Value in next, Config do
						if Flags[Index] then
							Flags[Index]:Set(Value)
						end
					end
				end
				--
				function Window:Move(Vector)
					for _, Drawing in next, Menu.Drawings do
						local Position = Vector
						if Drawing[2][2] then
							Position = Menu:Position(0, Drawing[2][1].X, 0, Drawing[2][1].Y, Drawing[2][2])
						end
						Drawing[1].Position = Position
					end
				end
				--
				function Window:IsOverContent()
					if Window.CurrentContent and Window.CurrentContent.Frame then
						local FrameX = Window.CurrentContent.Frame.Position.X
						local FrameY = Window.CurrentContent.Frame.Position.Y
						--
						return Menu:MouseOverDrawing({ FrameX, FrameY, FrameX + Frame.Size.X, FrameY + Frame.Size.Y })
					end
					--
					return false
				end
				--
				function Window:CloseContent()
					if Window.CurrentContent.Dropdown and Window.CurrentContent.Dropdown.Open then
						local Dropdown = Window.CurrentContent.Dropdown
						Dropdown.Open = not Dropdown.Open
						--
						for _, Drawing in next, Dropdown.Holder.Drawings do
							Menu:Remove(Drawing)
						end
						--
						Dropdown.Holder.Drawings = {}
						Dropdown.Holder.Buttons = {}
						Dropdown.Holder.Inline = nil
						--
						Window.CurrentContent.Frame = nil
						Window.CurrentContent.Dropdown = nil
					elseif Window.CurrentContent.Colorpicker and Window.CurrentContent.Colorpicker.Open then
						local Colorpicker = Window.CurrentContent.Colorpicker
						Colorpicker.Open = not Colorpicker.Open
						--
						for _, Drawing in next, Colorpicker.Holder.Drawings do
							Menu:Remove(Drawing)
						end
						--
						Colorpicker.Holder.Drawings = {}
						--
						Window.CurrentContent.Frame = nil
						Window.CurrentContent.Colorpicker = nil
					elseif Window.CurrentContent.Keybind and Window.CurrentContent.Keybind.Open then
						local ModeMenu = Window.CurrentContent.Keybind.ModeMenu
						Window.CurrentContent.Keybind.Open = not Window.CurrentContent.Keybind.Open
						--
						for _, Drawing in next, ModeMenu.Drawings do
							Menu:Remove(Drawing)
						end
						--
						ModeMenu.Drawings = {}
						ModeMenu.Buttons = {}
						ModeMenu.Frame = nil
						--
						Window.CurrentContent.Frame = nil
						Window.CurrentContent.Keybind = nil
					end
				end
				--
				function Window:Fade(Bool)
					Window.Fading = true
					Window.IsVisible = Bool
					--
					local Transp = Bool and 1 or 0
					--
					Spawn(function()
						for _, Value in next, Menu.Drawings do
							Menu:Lerp(Value[1], { Transparency = Transp * Value[3] }, 0.25)
						end
						--
						for _, Value in pairs({ Window.Cursor["Cursor"], Window.Cursor["CursorInline"] }) do
							Menu:Lerp(Value, { Transparency = Transp }, 0.25)
						end
					end)
					--
					UserInputService.MouseIconEnabled = not Bool
					--
					Window.Fading = false
				end
				--
				function Window:Cursor()
					Window.Cursor = {}
					--
					local Cursor = Menu:Create("Triangle", nil, {
						Color = Theme.Colors.Accent,
						Thickness = 3,
						Filled = false,
						ZIndex = 9999,
						Hidden = true,
					})
					Window.Cursor["Cursor"] = Cursor
					--
					local CursorInline = Menu:Create("Triangle", nil, {
						Color = Theme.Colors.A,
						Thickness = 1,
						ZIndex = 10000,
						Hidden = true,
					})
					Window.Cursor["CursorInline"] = CursorInline
					--
					UserInputService.MouseIconEnabled = false
					--
					Monolith:NewConnection("CURSOR", Menu.Connections, RenderStepped, function()
						if Window.IsVisible then
							local MouseX = Monolith.MousePosition.X
							local MouseY = Monolith.MousePosition.Y
							--
							Cursor.PointA = NewVector2(MouseX, MouseY)
							Cursor.PointB = NewVector2(MouseX + 10, MouseY + 4)
							Cursor.PointC = NewVector2(MouseX + 4, MouseY + 10)
							--
							CursorInline.PointA = NewVector2(MouseX, MouseY)
							CursorInline.PointB = NewVector2(MouseX + 10, MouseY + 4)
							CursorInline.PointC = NewVector2(MouseX + 4, MouseY + 10)
						end
					end)
					--
					return Window.Cursor
				end
				--
				function Window:Watermark()
					Window.Watermark = { Drawings = {}, Visible = true }
					--
					local Name = Format(
						"Monolith / %s / %s ms / %d fps / %s",
						Monolith.Shared.User,
						Monolith.Shared.Ping,
						Monolith.Shared.Fps,
						os.date("%b. %d, %Y")
					)
					local TextBounds = Menu:GetTextBounds(Name, Theme.Text.Size, Theme.Text.Font)
					--
					local Outline = Menu:Create("Frame", { NewVector2(Monolith.ScreenSizeFix.X * 0.05, 4) }, {
						Position = Menu:Position(0.05, 0, 0, 4),
						Size = Menu:Size(0, TextBounds.X + 37, 0, 30),
						Visible = Window.Watermark.Visible,
						Color = Theme.Colors.A,
						Hidden = true,
						Transparency = 0,
					}, Window.Watermark.Drawings)
					--
					local Inline = Menu:Create("Frame", { NewVector2(1, 1), Outline }, {
						Position = Menu:Position(0, 1, 0, 1, Outline),
						Size = Menu:Size(1, -2, 1, -2, Outline),
						Visible = Window.Watermark.Visible,
						Color = Theme.Colors.C,
						Hidden = true,
						Transparency = 0,
					}, Window.Watermark.Drawings)
					--
					local Gradient = Menu:Create("Image", { NewVector2(0, 1), Inline }, {
						Position = Menu:Position(0, 0, 0, 1, Inline),
						Size = Menu:Size(1, 0, 1, 0, Inline),
						Hidden = true,
						Transparency = 0,
					}, Window.Watermark.Drawings)
					--
					Menu:LoadImage(Gradient, "Gradient")
					--
					local Logo = Menu:Create("Image", { NewVector2(0, -1), Outline }, { -- -1, -1
						Position = Menu:Position(0, 0, 0, -1, Outline),
						Size = Menu:Size(0, 32, 0, 32, Outline), -- 64, 64
						Color = NewRGB(255, 255, 255),
						Hidden = true,
						Transparency = 0,
					}, Window.Watermark.Drawings)
					Menu:LoadImage(Logo, "Monolith")
					--
					local Text = Menu:Create("TextLabel", { NewVector2(32, 10), Outline }, {
						Text = Name,
						Position = Menu:Position(0, 32, 0, 10, Outline),
						Visible = Window.Watermark.Visible,
						OutlineColor = Theme.Text.Outline,
						Color = Theme.Text.Color,
						Font = Theme.Text.Font,
						Hidden = true,
						Size = 11,
						Transparency = 0,
					}, Window.Watermark.Drawings)
					--
					function Window.Watermark:UpdateSize()
						Outline.Size = Menu:Size(0, TextBounds.X + 37, 0, 30)
						Inline.Size = Menu:Size(1, -2, 1, -2, Outline)
						Gradient.Size = Menu:Size(1, 0, 1, 0, Inline)
					end
					--
					function Window.Watermark:Fade(Bool)
						Spawn(function()
							for Index, Value in next, Window.Watermark.Drawings do
								Menu:Lerp(Value, { Transparency = Bool and 1 or 0 }, 0.25)
							end
						end)
					end
					--
					Window.Watermark:UpdateSize()
					--
					Spawn(function()
						local Count = 0
						Monolith:NewConnection("FPS COUNTER", Menu.Connections, RenderStepped, function()
							Count = Count + 1
						end)
						--
						while Wait(1) do
							if Monolith and Monolith.Shared then
								Monolith.Shared.Fps = Count
								Monolith.Shared.Ping = tostring(
									Round(Stats.Network.ServerStatsItem["Data Ping"]:GetValue())
								) or "???"
								--
								Text.Text = Format(
									"Monolith / %s / %s ms / %d fps / %s",
									Monolith.Shared.User,
									Monolith.Shared.Ping,
									Monolith.Shared.Fps,
									os.date("%b. %d, %Y")
								)
								TextBounds = Menu:GetTextBounds(Text.Text, Theme.Text.Size, Theme.Text.Font)
								Window.Watermark:UpdateSize()
							end
							--
							Count = 0
						end
					end)
					--
					return Window.Watermark
				end
				--
				function Window:KeybindsList(Info)
					Window.KeybindsList = { Visible = true, Keybinds = {}, Drawings = {} }
					--
					local Info = Info or {}
					--
					local KeybindsList_Outline = Menu:Create(
						"Frame",
						{ NewVector2(10, (Monolith.ScreenSizeFix.Y / 2) - 200) },
						{
							Size = Menu:Size(0, 180, 0, 22),
							Position = Menu:Position(0, 10, 0.4, 0),
							Visible = true,
							Hidden = true,
							Color = Theme.Colors.A,
							Transparency = 0,
						},
						Window.KeybindsList.Drawings
					)
					--
					local KeybindsList_Frame = Menu:Create("Frame", { NewVector2(1, 1), KeybindsList_Outline }, {
						Size = Menu:Size(1, -2, 1, -2, KeybindsList_Outline),
						Position = Menu:Position(0, 1, 0, 1, KeybindsList_Outline),
						Hidden = true,
						Color = Theme.Colors.C,
						Visible = true,
						Transparency = 0,
					}, Window.KeybindsList.Drawings)
					--
					local KeybindsList_Text = Menu:Create(
						"TextLabel",
						{ NewVector2(KeybindsList_Outline.Size.X / 2, 5), KeybindsList_Outline },
						{
							Text = "KEYBINDS",
							Size = Theme.Text.Size,
							Font = Theme.Text.Font,
							Color = Theme.Text.Color,
							OutlineColor = Theme.Text.Outline,
							Center = true,
							Hidden = true,
							Position = Menu:Position(0.5, 0, 0, 5, KeybindsList_Outline),
							Visible = true,
							Transparency = 0,
						},
						Window.KeybindsList.Drawings
					)
					--
					function Window.KeybindsList:Fade(Bool)
						for _, Drawing in next, Window.KeybindsList.Drawings do
							Menu:Lerp(Drawing, { Transparency = Bool and 1 or 0 }, 0.25)
						end
						Window.KeybindsList.Visible = Bool
					end
					--
					function Window.KeybindsList:Resort()
						local Index = 0
						for i, v in pairs(Window.KeybindsList.Keybinds) do
							v:Move(0 + (Index * 17))
							--
							Index = Index + 1
						end
					end
					--
					function Window.KeybindsList:Add(KeybindName, KeybindValue)
						if KeybindName and KeybindValue and not Window.KeybindsList.Keybinds[KeybindName] then
							local KeybindTable = {}
							--
							local Keybind_Outline = Menu:Create(
								"Frame",
								{ NewVector2(0, KeybindsList_Outline.Size.Y - 1), KeybindsList_Outline },
								{
									Size = Menu:Size(1, 0, 0, 18, KeybindsList_Outline),
									Position = Menu:Position(0, 0, 1, -1, KeybindsList_Outline),
									Hidden = true,
									Color = Theme.Colors.A,
									Visible = Window.KeybindsList.Visible,
								}
							)
							--
							local Keybind_Frame = Menu:Create("Frame", { NewVector2(1, 1), Keybind_Outline }, {
								Size = Menu:Size(1, -2, 1, -2, Keybind_Outline),
								Position = Menu:Position(0, 1, 0, 1, Keybind_Outline),
								Hidden = true,
								Color = Theme.Colors.C,
								Visible = Window.KeybindsList.Visible,
							})
							--
							local Keybind_Text = Menu:Create("TextLabel", { NewVector2(4, 3), Keybind_Outline }, {
								Text = KeybindName,
								Size = Theme.Text.Size,
								Font = Theme.Text.Font,
								Color = Theme.Text.Color,
								OutlineColor = Theme.Text.Outline,
								Center = false,
								Hidden = true,
								Position = Menu:Position(0, 4, 0, 3, Keybind_Outline),
								Visible = Window.KeybindsList.Visible,
							})
							--
							local TextBounds = Menu:GetTextBounds(KeybindName, Theme.Text.Size, Theme.Text.Font).X
							local Keybind_Value = Menu:Create(
								"TextLabel",
								{ NewVector2(Keybind_Outline.Size.X - 4 - TextBounds, 3), Keybind_Outline },
								{
									Text = "[" .. KeybindValue .. "]",
									Size = Theme.Text.Size,
									Font = Theme.Text.Font,
									Color = Theme.Text.Color,
									OutlineColor = Theme.Text.Outline,
									Hidden = true,
									Position = Menu:Position(1, -4 - TextBounds, 0, 3, Keybind_Outline),
									Visible = Window.KeybindsList.Visible,
								}
							)
							--
							function KeybindTable:Move(yPos)
								Keybind_Outline.Position = Menu:Position(0, 0, 1, -1 + yPos, KeybindsList_Outline)
								Keybind_Frame.Position = Menu:Position(0, 1, 0, 1, Keybind_Outline)
								Keybind_Text.Position = Menu:Position(0, 4, 0, 2, Keybind_Outline)
								Keybind_Value.Position =
									Menu:Position(1, -4 - Keybind_Value.TextBounds.X, 0, 2, Keybind_Outline)
							end
							--
							function KeybindTable:Remove()
								Menu:Remove(Keybind_Outline, true)
								Menu:Remove(Keybind_Frame, true)
								Menu:Remove(Keybind_Text, true)
								Menu:Remove(Keybind_Value, true)
								--
								Window.KeybindsList.Keybinds[KeybindName] = nil
								KeybindTable = nil
							end
							--
							function KeybindTable:Visibility()
								Keybind_Outline.Visible = Window.KeybindsList.Visible
								Keybind_Frame.Visible = Window.KeybindsList.Visible
								Keybind_Text.Visible = Window.KeybindsList.Visible
								Keybind_Value.Visible = Window.KeybindsList.Visible
							end
							--
							Window.KeybindsList.Keybinds[KeybindName] = KeybindTable
							Window.KeybindsList:Resort()
						end
					end
					--
					function Window.KeybindsList:Remove(KeybindName)
						if KeybindName and Window.KeybindsList.Keybinds[KeybindName] then
							Window.KeybindsList.Keybinds[KeybindName]:Remove()
							Window.KeybindsList.Keybinds[KeybindName] = nil
							Window.KeybindsList:Resort()
						end
					end
					--
					function Window.KeybindsList:Visibility()
						KeybindsList_Outline.Visible = Window.KeybindsList.Visible
						KeybindsList_Inline.Visible = Window.KeybindsList.Visible
						KeybindsList_Frame.Visible = Window.KeybindsList.Visible
						KeybindsList_Accent.Visible = Window.KeybindsList.Visible
						KeybindsList_Text.Visible = Window.KeybindsList.Visible
						--
						for _, Keybind in pairs(Window.KeybindsList.Keybinds) do
							Keybind:Visibility()
						end
					end
					--
					function Window.KeybindsList:Update(UpdateType, UpdateValue)
						if UpdateType == "Visible" then
							Window.KeybindsList.Visible = UpdateValue
							Window.KeybindsList:Visibility()
						end
					end
					--
					return Window.KeybindsList
				end
				--
				function Window:Initialize()
					Window.Tabs[1]:Show()
					--
					for Index, Tab in next, Window.Tabs do
						Tab:Update()
					end
					--
					Window:Cursor()
					Window:Watermark()
					Window:KeybindsList()
					--
					Monolith.Shared.Menu = true
				end
				--
				Menu.Inputs.Began[#Menu.Inputs.Began + 1] = function(Input)
					if
						Input.UserInputType == Enum.UserInputType.MouseButton1
						and Window.IsVisible
						and Menu:MouseOverDrawing({
							DragFrame.Position.X,
							DragFrame.Position.Y,
							DragFrame.Position.X + DragFrame.Size.X,
							DragFrame.Position.Y + DragFrame.Size.Y,
						})
					then
						Window.Dragging = true
						Window.Drag = NewVector2(
							Monolith.MousePosition.X - DragFrame.Position.X,
							Monolith.MousePosition.Y - DragFrame.Position.Y
						)
					end
				end
				--
				Menu.Inputs.Ended[#Menu.Inputs.Ended + 1] = function(Input)
					if
						Input.UserInputType == Enum.UserInputType.MouseButton1
						and Window.IsVisible
						and Window.Dragging
					then
						Window.Dragging = false
						Window.Drag = NewVector2(0, 0)
					end
				end
				--
				Menu.Inputs.Changed[#Menu.Inputs.Changed + 1] = function()
					if Window.Dragging and Window.IsVisible then
						local MoveX = Clamp(
							Monolith.MousePosition.X - Window.Drag.X,
							5,
							Monolith.ScreenSize.X - MainFrame.Size.X - 5
						)
						local MoveY = Clamp(
							Monolith.MousePosition.Y - Window.Drag.Y,
							5,
							Monolith.ScreenSize.Y - MainFrame.Size.Y - 5
						)
						local Move = NewVector2(MoveX, MoveY)
						Window:Move(Move)
					end
				end
				--
				Menu.Inputs.Began[#Menu.Inputs.Began + 1] = function(Input)
					if Input.KeyCode == Window.UiBind then
						Window:Fade(not Window.IsVisible)
					end
					--
				end
				--
				Monolith:NewConnection("INPUT BEGAN", Menu.Connections, UserInputService.InputBegan, function(Input)
					for _, Function in next, Menu.Inputs.Began do
						if not Window.Dragging then
							local e, s = pcall(function()
								Function(Input)
							end)
						else
							break
						end
					end
				end)
				--
				Monolith:NewConnection(
					"INPUT CHANGED [DRAG]",
					Menu.Connections,
					UserInputService.InputChanged,
					function(Input)
						for _, Function in next, Menu.Inputs.Changed do
							if not Window.Dragging then
								local e, s = pcall(function()
									Function(Input)
								end)
							else
								break
							end
						end
					end
				)
				--
				Monolith:NewConnection("INPUT ENDED", Menu.Connections, UserInputService.InputEnded, function(Input)
					for _, Function in next, Menu.Inputs.Ended do
						local e, s = pcall(function()
							Function(Input)
						end)
					end
				end)
				--
				Monolith:NewConnection("INPUT CHANGED", Menu.Connections, UserInputService.InputChanged, function()
					for _, Function in next, Menu.Inputs.Changed do
						local e, s = pcall(function()
							Function()
						end)
					end
				end)
				--
				Monolith:NewConnection(
					"SCREEN AUTO SIZER",
					Menu.Connections,
					Camera:GetPropertyChangedSignal("ViewportSize"),
					function()
						Monolith.ScreenSize = Camera.ViewportSize
						Monolith.ScreenSizeFix =
							NewVector2(Math:RoundToEven(Monolith.ScreenSize.X), Math:RoundToEven(Monolith.ScreenSize.Y))
						--
						Window:Move(
							NewVector2(
								(Monolith.ScreenSize.X / 2) - (Size.X / 2),
								(Monolith.ScreenSize.Y / 2) - (Size.Y / 2)
							)
						)
					end
				)
				--
				return setmetatable(Window, Menu)
			end
			--
			function Menu:Tab(Info)
				local Info = Info or {}
				--
				local Window = self
				local Tab = {
					Number = #Window.Tabs,
					Open = false,
					Sections = {},
					SectionOffset = { left = 0, right = 0 },
					Window = Window,
					VisibleContent = {},
				}
				--
				local Position = Window.TabAmmount + Window.DragFrame.Size.Y * 1.48
				--
				for _, Value in next, Window.Tabs do
					Position = Position + (Value.TabButton.Size.Y + 10)
				end
				--
				Window.Tabs[#Window.Tabs + 1] = Tab
				--
				local TabButton = Menu:Create("Frame", { NewVector2(1, Position), Window.MainFrame }, {
					Size = Menu:Size(
						0,
						Window.TabAmmount
							and (((Window.TabHolder.Size.X * 5) - ((Window.TabAmmount - 1) * 2)) / Window.TabAmmount),
						0,
						50
					),
					Position = Menu:Position(0, 1, 0, Position, Window.MainFrame),
					Color = Theme.Colors.C,
					Visible = Tab.Open,
					Transparency = 0,
				}, Tab.VisibleContent)
				Tab["TabButton"] = TabButton
				--
				local Image = Menu:Create("Image", { NewVector2(8, 2), TabButton }, {
					Size = Menu:Size(0, 48, 0, 48, TabButton),
					Position = Menu:Position(0, 8, 0, 2, TabButton),
				})
				Menu:LoadImage(Image, tostring(Tab.Number))
				Tab["Image"] = Image
				--
				function Tab:Update()
					local MainFrameX = Window["MainFrame"].Size.X
					local SectionHolderX = Window["SectionHolder"].Size.X

					Tab.SectionOffset["left"] = 0
					Tab.SectionOffset["right"] = 0
					--
					for _, Value in next, Tab.Sections do
						if Value.Side then -- +50                           --9
							Menu:UpdateOffset(
								Value.SectionOutline,
								{
									NewVector2(
										Value.Side == "right" and (MainFrameX / 2) + 43 or SectionHolderX / 5 - 18,
										84 + Tab["SectionOffset"][Value.Side]
									),
									Window.MainFrame,
								}
							) -- 108
							Value:Update(Tab.SectionOffset[Value.Side] + 10)
							Tab.SectionOffset[Value.Side] = Tab.SectionOffset[Value.Side]
								+ Value.SectionOutline.Size.Y
								+ 10
						end
					end
					--
					Window:Move(Window["MainFrame"].Position)
				end
				--
				function Tab:Show()
					if Window.CurrentTab then
						Window.CurrentTab.Open = false

						Menu:LoadImage(Window.CurrentTab["Image"], tostring(Window.CurrentTab.Number))

						for _, Value in ipairs(Window.CurrentTab.VisibleContent) do
							Value.Visible = false
						end

						for _, Section in ipairs(Window.CurrentTab.Sections) do
							for _, Value in ipairs(Section.VisibleContent) do
								Value.Visible = false
							end
						end

						Window:CloseContent()
					end

					Window.CurrentTab = Tab
					Tab.Open = true

					Menu:LoadImage(Tab["Image"], tostring(Tab.Number .. " Selected"))

					for _, Value in ipairs(Tab.VisibleContent) do
						Value.Visible = true
					end

					for _, Section in ipairs(Tab.Sections) do
						for _, Value in ipairs(Section.VisibleContent) do
							Value.Visible = true
						end
					end
				end
				--
				Menu.Inputs.Began[#Menu.Inputs.Began + 1] = function(Input)
					if
						Input.UserInputType == Enum.UserInputType.MouseButton1
						and Window.IsVisible
						and Menu:MouseOverDrawing({
							TabButton.Position.X,
							TabButton.Position.Y,
							TabButton.Position.X + TabButton.Size.X,
							TabButton.Position.Y + TabButton.Size.Y,
						})
						and Window.CurrentTab ~= Tab
					then
						Tab:Show()
					end
				end
				--
				return setmetatable(Tab, Menu.Tabs)
			end
			--
			function Menu.Tabs:MultiSection(Info)
				local Info = Info or {}
				local MSections = Info.Sections or Info.sections or {}
				local Side = Info.Side or Info.side or "left"
				local Size = Info.Size or Info.size or 150
				local Fill = Info.Fill or Info.fill or true
				local Callback = Info.Callback or Info.callback or function() end
				Side = Side:lower()
				local Window = self.Window
				local Tab = self
				local MultiSection = {
					Window = Window,
					Tab = Tab,
					Sections = {},
					Backup = {},
					VisibleContent = {},
					CurrentSection = nil,
					Side = Side,
				}
				--
				local SectionOutline = Menu:Create(
					"Frame",
					{
						NewVector2(
							Side == "right" and (Window.SectionHolder.Size.X / 2) + 50 or 5,
							5 + Tab["SectionOffset"][Side]
						),
						Window.SectionHolder,
					},
					{
						Position = Menu:Position(
							0.5,
							Side == "right" and 50 or 5,
							0,
							34 + Tab.SectionOffset[Side],
							Window.SectionHolder
						),
						Size = Menu:Size(0.5, -44, 0, Size, Window.SectionHolder), -- 0.5, -64
						Color = Theme.Colors.A,
						Visible = Tab.Open,
					},
					MultiSection.VisibleContent
				)
				MultiSection["SectionOutline"] = SectionOutline
				--
				local SectionInline = Menu:Create("Frame", { NewVector2(1, 1), SectionOutline }, {
					Position = Menu:Position(0, 1, 0, 1, SectionOutline),
					Size = Menu:Size(1, -2, 1, -1, SectionOutline),
					Color = Theme.Colors.C,
					Visible = Tab.Open,
				}, MultiSection.VisibleContent)
				--
				local SectionUpperTop = Menu:Create("Frame", { NewVector2(0, -16), SectionOutline }, {
					Position = Menu:Position(0, 0, 0, -16, SectionOutline),
					Size = Menu:Size(1, 0, 0, 17, SectionOutline),
					Color = Theme.Colors.A,
					Visible = Tab.Open,
				}, MultiSection.VisibleContent)
				--
				local SectionUpper = Menu:Create("Frame", { NewVector2(1, 1), SectionUpperTop }, {
					Position = Menu:Position(0, 1, 0, 1, SectionUpperTop),
					Size = Menu:Size(1, -2, 1, -2, SectionUpperTop),
					Color = Theme.Colors.C,
					Visible = Tab.Open,
					Filled = true,
				}, MultiSection.VisibleContent)
				--
				function MultiSection:Update(Padding) -- -64
					SectionOutline.Size = Menu:Size(
						0.5,
						-44,
						0,
						Fill and (Window.SectionHolder.Size.Y - 50 - (Padding or 0))
							or (Size or (Section.CurrentAxis + 4)),
						Window.SectionHolder
					)
					SectionInline.Size = Menu:Size(1, -2, 1, -2, SectionOutline)
					--
					for Index, Value in next, MultiSection.Sections do
						Value:Update(Padding)
					end
				end
				--
				for Index, Value in next, MSections do
					local MSection = {
						Window = Window,
						Tab = Tab,
						CurrentAxis = 10,
						Sections = {},
						VisibleContent = {},
						SectionOutline = SectionOutline,
						Parent = MultiSection,
					}
					--
					local TextBounds = Menu:GetTextBounds(Value, Theme.Text.Size, Theme.Text.Font)
					--
					local MSectionFrame = Menu:Create(
						"Frame",
						{ NewVector2(((Index - 1) * (1 / #MSections)) * SectionUpper.Size.X, 0), SectionUpper },
						{
							Size = Menu:Size(1 / #MSections, 0, 1, 0, SectionUpper),
							Position = Menu:Position((Index - 1) * (1 / #MSections), 0, 0, 0, SectionUpper),
							Color = Index == 1 and Theme.Colors.D or Theme.Colors.C,
							Visible = Tab.Open,
						},
						MultiSection.VisibleContent
					)
					MSection["Frame"] = MSectionFrame
					--
					if Index ~= 1 then
						local MSectionSeparator = Menu:Create("Frame", { NewVector2(0, 0), MSectionFrame }, {
							Position = Menu:Position(0, 0, 0, 0, MSectionFrame),
							Size = Menu:Size(0, 1, 1, 0, MSectionFrame),
							Color = Theme.Colors.A,
							Visible = Tab.Open,
						}, MultiSection.VisibleContent)
					end
					--
					local MSectionUnder = Menu:Create(
						"Frame",
						{ NewVector2(Index == 1 and 0 or 1, MSectionFrame.Size.Y), MSectionFrame },
						{
							Position = Menu:Position(0, Index == 1 and 0 or 1, 0, MSectionFrame.Size.Y, MSectionFrame),
							Size = Menu:Size(1, Index == 1 and 0 or -1, 0, 1, MSectionFrame),
							Color = Theme.Colors.C,
							Transparency = Index == 1 and 1 or 0,
							Visible = Tab.Open,
						},
						MultiSection.VisibleContent
					)
					MSection["Under"] = MSectionUnder
					--
					local MSectionGradient = Menu:Create("Image", { NewVector2(0, 0), MSectionFrame }, {
						Position = Menu:Position(0, 0, 0, 0, MSectionFrame),
						Size = Menu:Size(1, 0, 1, 0, MSectionFrame),
						Visible = Tab.Open,
						Transparency = 0.8,
					}, MultiSection.VisibleContent)
					--
					local MSectionTitle = Menu:Create(
						"TextLabel",
						{ NewVector2(MSectionFrame.Size.X / 2, 3), MSectionFrame },
						{
							Position = Menu:Position(0.5, 0, 1, 3, MSectionFrame),
							OutlineColor = Theme.Text.Outline,
							Color = Theme.Text.Color,
							Size = Theme.Text.Size,
							Font = Theme.Text.Font,
							Transparency = Index == 1 and 1 or 0.5,
							Visible = Tab.Open,
							Center = true,
							Text = Value,
						},
						MultiSection.VisibleContent
					)
					MSection["Title"] = MSectionTitle
					--
					Menu:LoadImage(MSectionGradient, "Gradient")
					--
					function MSection:Update()
						if MultiSection.CurrentSection == MSection then
							MultiSection.VisibleContent =
								Menu:Combine(MultiSection.Backup, MultiSection.CurrentSection.VisibleContent)
						else
							for _, Value in next, MSection.VisibleContent do
								Value.Visible = false
							end
						end
					end
					--
					Menu.Inputs.Began[#Menu.Inputs.Began + 1] = function(Input)
						if
							Input.UserInputType == Enum.UserInputType.MouseButton1
							and Window.IsVisible
							and Tab.Open
							and Menu:MouseOverDrawing({
								MSectionFrame.Position.X,
								MSectionFrame.Position.Y,
								MSectionFrame.Position.X + MSectionFrame.Size.X,
								MSectionFrame.Position.Y + MSectionFrame.Size.Y,
							})
							and MultiSection.CurrentSection ~= MSection
							and not Window:IsOverContent()
						then
							local CurrentSection = MultiSection.CurrentSection
							local Title = CurrentSection["Title"]
							local Under = CurrentSection["Under"]

							CurrentSection.Frame.Color = Theme.Colors.C
							Menu:Lerp(Title, { Transparency = 0.5 }, 0.25)
							Menu:UpdateTransparency(Title, 0.5)
							Menu:Lerp(Under, { Transparency = 0 }, 0.25)
							Menu:UpdateTransparency(Under, 0)
							--
							for _, Value in next, CurrentSection.VisibleContent do
								Value.Visible = false
							end
							--
							MultiSection.CurrentSection = MSection
							--
							local CurrentSection = MultiSection.CurrentSection
							local Title = CurrentSection["Title"]
							local Under = CurrentSection["Under"]
							--
							CurrentSection.Frame.Color = Theme.Colors.D
							Menu:Lerp(Title, { Transparency = 1 }, 0.25)
							Menu:UpdateTransparency(Title, 1)
							Menu:Lerp(Under, { Transparency = 1 }, 0.25)
							Menu:UpdateTransparency(Under, 1)
							--
							for _, Value in next, CurrentSection.VisibleContent do
								Value.Visible = true
							end
							--
							MultiSection.VisibleContent =
								Menu:Combine(MultiSection.Backup, CurrentSection.VisibleContent)
							--
							Callback(Value, MSection)
							Window:Move(Window.MainFrame.Position)
						end
					end
					--
					if Index == 1 then
						MultiSection.CurrentSection = MSection
						Callback(Value, MSection)
					end
					--
					MultiSection.Sections[#MultiSection.Sections + 1] = setmetatable(MSection, Menu.Sections)
				end
				--
				for Index, Value in next, MultiSection.VisibleContent do
					MultiSection.Backup[Index] = Value
				end
				--
				Tab.SectionOffset[Side] = Tab.SectionOffset[Side] + 100 + 5
				Tab.Sections[#Tab.Sections + 1] = MultiSection
				--
				return Unpack(MultiSection.Sections)
			end
			--
			function Menu.Sections:Toggle(Info)
				local Info = Info or {}
				local Name = Info.Name or Info.name or "New Toggle"
				local Def = Info.Default or Info.default or false
				local Safe = Info.Safe or Info.safe or nil
				Safe = Info.Safe == nil and true or false
				local Flag = Info.Flag or Info.flag or nil
				local Callback = Info.Callback or Info.callback or function() end
				--
				local Window = self.Window
				local Tab = self.Tab
				local Section = self
				--
				local Toggle = {
					Axis = Section.CurrentAxis,
					Safe = Safe,
					Current = Def,
					AddedAxis = 0,
					Colorpickers = 0,
					Sliders = 0,
					Keybind = nil,
				}
				--
				local Outline = Menu:Create("Frame", { NewVector2(10, Toggle.Axis), Section.SectionOutline }, {
					Size = Menu:Size(0, 10, 0, 10),
					Position = Menu:Position(0, 10, 0, Toggle.Axis, Section.SectionOutline),
					Color = Theme.Colors.A,
					Visible = Tab.Open,
					Transparency = Toggle.Current and 1 or 0,
				}, Section.VisibleContent)
				Toggle["Outline"] = Outline
				--
				local DisabledInline = Menu:Create(
					"Frame",
					{ NewVector2(1, 1), Outline },
					{ -- // Disabled Inline (i cant js change colors due to Toggle.Fade)
						Size = Menu:Size(1, -2, 1, -2, Outline),
						Position = Menu:Position(0, 1, 0, 1, Outline),
						Color = Theme.Colors.D,
						Visible = Tab.Open,
					},
					Section.VisibleContent
				)
				Toggle["DisabledInline"] = DisabledInline
				--
				local EnabledInline = Menu:Create(
					"Frame",
					{ NewVector2(1, 1), Outline },
					{ -- // Enabled Inline (i cant js change colors due to Toggle.Fade)
						Size = Menu:Size(1, -2, 1, -2, Outline),
						Position = Menu:Position(0, 1, 0, 1, Outline),
						Color = Theme.Colors.Accent,
						Transparency = Toggle.Current and 1 or 0,
						Visible = Tab.Open,
					},
					Section.VisibleContent
				)
				Toggle["EnabledInline"] = EnabledInline
				--
				local EnabledShadow = Menu:Create(
					"Frame",
					{ NewVector2(Section.Parent.Side == "left" and 1.2 or 1, 1), Outline },
					{ -- // Enabled Inline Outline (for shadows)
						Size = Menu:Size(1, -2, 1, -2, Outline),
						Position = Menu:Position(0, Section.Parent.Side == "left" and 1.2 or 1, 0, 1, Outline), -- 1.2
						Color = Theme.Colors.E,
						Visible = Tab.Open,
						Filled = false,
						Transparency = Toggle.Current and 1 or 0,
					},
					Section.VisibleContent
				)
				Toggle["EnabledShadow"] = EnabledShadow
				--
				local Text = Menu:Create("TextLabel", { NewVector2(15, 1), Outline }, { -- // Text
					Position = Menu:Position(0, 15, 0, 1, Outline),
					OutlineColor = Theme.Text.Outline,
					Color = Toggle.Safe and Theme.Text.Color or NewRGB(150, 0, 0),
					Size = Theme.Text.Size,
					Font = Theme.Text.Font,
					Visible = Tab.Open,
					Transparency = Toggle.Current and 1 or 0.6,
					Text = Name,
				}, Section.VisibleContent)
				Toggle["Text"] = Text
				--
				function Toggle:Get()
					return Toggle.Current
				end
				--
				function Toggle:Fade(Bool)
					for Index, Value in next, { Toggle["EnabledShadow"], Toggle["EnabledInline"], Toggle["Outline"] } do
						Menu:Lerp(Value, { Transparency = Bool and 1 or 0 }, 0.25)
						Menu:UpdateTransparency(Value, Bool and 1 or 0)
					end
					--
					Toggle["EnabledInline"].Color = Toggle.Current and Theme.Colors.Accent or Theme.Colors.D
					--
					Menu:Lerp(Toggle["Text"], { Transparency = Bool and 1 or 0.6 }, 0.25)
					Menu:UpdateTransparency(Toggle["Text"], Bool and 1 or 0.6)
				end
				--
				function Toggle:Set(Bool)
					if Bool or not Bool then
						Toggle.Current = Bool
						Toggle:Fade(Toggle.Current)
						--
						Callback(Toggle.Current)
					end
				end
				--
				function Toggle:Set_Callback(P_Callback)
					Callback = P_Callback
					Callback(self:Get())
				end
				--
				Menu.Inputs.Began[#Menu.Inputs.Began + 1] = function(Input)
					if
						Input.UserInputType == Enum.UserInputType.MouseButton1
						and Toggle["DisabledInline"].Visible
						and Window.IsVisible
						and Tab.Open
						and Menu:MouseOverDrawing({
							Section.SectionOutline.Position.X,
							Section.SectionOutline.Position.Y + Toggle.Axis,
							Section.SectionOutline.Position.X + Section.SectionOutline.Size.X - Toggle.AddedAxis,
							Section.SectionOutline.Position.Y + Toggle.Axis + 12,
						})
						and not Window:IsOverContent()
					then
						if not Toggle.Safe and Flags["Unsafe"]:Get() then
							Toggle.Current = not Toggle.Current
							Toggle:Fade(Toggle.Current)
							--
							Callback(Toggle.Current)
						elseif Toggle.Safe then
							Toggle.Current = not Toggle.Current
							Toggle:Fade(Toggle.Current)
							--
							Callback(Toggle.Current)
						end
					end
				end
				--
				if Flag and tostring(Flag) ~= "" and tostring(Flag) ~= " " and not Flags[tostring(Flag)] then
					Flags[tostring(Flag)] = Toggle
				end
				--
				Section.CurrentAxis = Section.CurrentAxis + 12 + 4
				Section:Update()
				--
				function Toggle:Colorpicker(Info)
					local Info = Info or {}
					local Def = Info.def or Info.Def or Info.default or Info.Default or NewRGB(255, 255, 255)
					local Alpha = Info.transparency
						or Info.Transparency
						or Info.transp
						or Info.Transp
						or Info.alpha
						or Info.Alpha
						or nil
					local Flag = Info.flag or Info.Flag or nil
					local Callback = Info.Callback or Info.Callback or Info.Callback or Info.Callback or function() end
					--
					local HH, SS, VV = Def:ToHSV()
					local Colorpicker = {
						Toggle = Toggle,
						Axis = Toggle.Axis,
						Index = Toggle.Colorpickers,
						Current = { HH, SS, VV, (Alpha or 0) },
						Holding = { Picker = false, Huepicker = false, Transparency = false },
						Holder = {
							Inline = nil,
							Picker = nil,
							Picker_Cursor = nil,
							Huepicker = nil,
							Huepicker_Cursor = {},
							Transparency = nil,
							Transparencybg = nil,
							Transparency_Cursor = {},
							Drawings = {},
						},
					}
					--
					local Outline = Menu:Create(
						"Frame",
						{
							NewVector2(
								Section.SectionOutline.Size.X - (Toggle.Colorpickers == 0 and (30 + 4) or (54 + 4)),
								Colorpicker.Axis
							),
							Section.SectionOutline,
						},
						{
							Size = Menu:Size(0, 20, 0, 10),
							Position = Menu:Position(
								1,
								-(Toggle.Colorpickers == 0 and (30 + 4) or (54 + 4)),
								0,
								Colorpicker.Axis,
								Section.SectionOutline
							),
							Color = Theme.Colors.A,
							Visible = Tab.Open,
						},
						Section.VisibleContent
					)
					--
					local Transp
					--
					if Alpha then
						Transp = Menu:Create("Image", { NewVector2(1, 1), Outline }, {
							Size = Menu:Size(1, -2, 1, -2, Outline),
							Position = Menu:Position(0, 1, 0, 1, Outline),
							Visible = Tab.Open,
						}, Section.VisibleContent)
						--
						Menu:LoadImage(Transp, "CpTransparency")
					end
					--
					local Frame = Menu:Create("Frame", { NewVector2(1, 1), Outline }, {
						Size = Menu:Size(1, -2, 1, -2, Outline),
						Position = Menu:Position(0, 1, 0, 1, Outline),
						Color = Def,
						Transparency = Alpha and (1 - Alpha) or 1,
						Visible = Tab.Open,
					}, Section.VisibleContent)
					--
					local Gradient = Menu:Create("Image", { NewVector2(0, 0), Frame }, {
						Size = Menu:Size(1, 0, 1, 0, Frame),
						Position = Menu:Position(0, 0, 0, 0, Frame),
						Transparency = 0.7,
						Visible = Tab.Open,
					}, Section.VisibleContent)
					--
					Menu:LoadImage(Gradient, "Gradient")
					--
					function Colorpicker:Set(Color, Transp)
						if typeof(Color) == "table" then
							if Color.Color and Color.Transparency then
								local H, S, V = Unpack(Color.Color)
								Colorpicker.Current = { H, S, V, Color.Transparency }
								Frame.Color = Color3.fromHSV(
									Colorpicker.Current[1],
									Colorpicker.Current[2],
									Colorpicker.Current[3]
								)
								Frame.Transparency = 1 - Colorpicker.Current[4]
								Callback({
									Color = Color3.fromHSV(
										Colorpicker.Current[1],
										Colorpicker.Current[2],
										Colorpicker.Current[3]
									),
									Transparency = Colorpicker.Current[4],
								})
							else
								Colorpicker.Current = Color
								Frame.Color = Color3.fromHSV(
									Colorpicker.Current[1],
									Colorpicker.Current[2],
									Colorpicker.Current[3]
								)
								Frame.Transparency = 1 - Colorpicker.Current[4]
								Callback({
									Color = Color3.fromHSV(
										Colorpicker.Current[1],
										Colorpicker.Current[2],
										Colorpicker.Current[3]
									),
									Transparency = Colorpicker.Current[4],
								})
							end
						elseif typeof(Color) == "Color3" then
							local H, S, V = Color:ToHSV()
							Colorpicker.Current = { H, S, V, (Transp or 0) }
							Frame.Color =
								Color3.fromHSV(Colorpicker.Current[1], Colorpicker.Current[2], Colorpicker.Current[3])
							Frame.Transparency = 1 - Colorpicker.Current[4]
							Callback({
								Color = Color3.fromHSV(
									Colorpicker.Current[1],
									Colorpicker.Current[2],
									Colorpicker.Current[3]
								),
								Transparency = Colorpicker.Current[4],
							})
						end
					end
					--
					function Colorpicker:Set_Callback(P_Callback)
						Callback = P_Callback
						Callback(self:Get())
					end
					--
					function Colorpicker:Refresh()
						if Colorpicker.Open and Colorpicker.Holder.Picker and Colorpicker.Holding.Picker then
							Colorpicker.Current[2] = Clamp(
								Monolith.MousePosition.X - Colorpicker.Holder.Picker.Position.X,
								0,
								Colorpicker.Holder.Picker.Size.X
							) / Colorpicker.Holder.Picker.Size.X
							--
							Colorpicker.Current[3] = 1
								- (
									Clamp(
										Monolith.MousePosition.Y - Colorpicker.Holder.Picker.Position.Y,
										0,
										Colorpicker.Holder.Picker.Size.Y
									) / Colorpicker.Holder.Picker.Size.Y
								)
							--
							Colorpicker.Holder.Picker_Cursor.Position = Menu:Position(
								Colorpicker.Current[2],
								-3,
								1 - Colorpicker.Current[3],
								-3,
								Colorpicker.Holder.Picker
							)
							--
							Menu:UpdateOffset(
								Colorpicker.Holder.Picker_Cursor,
								{
									NewVector2(
										(Colorpicker.Holder.Picker.Size.X * Colorpicker.Current[2]) - 3,
										(Colorpicker.Holder.Picker.Size.Y * (1 - Colorpicker.Current[3])) - 3
									),
									Colorpicker.Holder.Picker,
								}
							)
							--
							if Colorpicker.Holder.Transparencybg then
								Colorpicker.Holder.Transparencybg.Color = Color3.fromHSV(
									Colorpicker.Current[1],
									Colorpicker.Current[2],
									Colorpicker.Current[3]
								)
							end
						elseif Colorpicker.Open and Colorpicker.Holder.Huepicker and Colorpicker.Holding.Huepicker then
							Colorpicker.Current[1] = (
								Clamp(
									Monolith.MousePosition.Y - Colorpicker.Holder.Huepicker.Position.Y,
									0,
									Colorpicker.Holder.Huepicker.Size.Y
								) / Colorpicker.Holder.Huepicker.Size.Y
							)
							--
							Colorpicker.Holder.Huepicker_Cursor[1].Position =
								Menu:Position(0, -3, Colorpicker.Current[1], -3, Colorpicker.Holder.Huepicker)
							Colorpicker.Holder.Huepicker_Cursor[2].Position =
								Menu:Position(0, 1, 0, 1, Colorpicker.Holder.Huepicker_Cursor[1])
							Colorpicker.Holder.Huepicker_Cursor[3].Position =
								Menu:Position(0, 1, 0, 1, Colorpicker.Holder.Huepicker_Cursor[2])
							Colorpicker.Holder.Huepicker_Cursor[3].Color = Color3.fromHSV(Colorpicker.Current[1], 1, 1)
							--
							Menu:UpdateOffset(
								Colorpicker.Holder.Huepicker_Cursor[1],
								{
									NewVector2(-3, (Colorpicker.Holder.Huepicker.Size.Y * Colorpicker.Current[1]) - 3),
									Colorpicker.Holder.Huepicker,
								}
							)
							--
							Colorpicker.Holder.Background.Color = Color3.fromHSV(Colorpicker.Current[1], 1, 1)
							--
							if Colorpicker.Holder.Transparency_Cursor and Colorpicker.Holder.Transparency_Cursor[3] then
								Colorpicker.Holder.Transparency_Cursor[3].Color =
									Color3.fromHSV(0, 0, 1 - Colorpicker.Current[4])
							end
							--
							if Colorpicker.Holder.Transparencybg then
								Colorpicker.Holder.Transparencybg.Color = Color3.fromHSV(
									Colorpicker.Current[1],
									Colorpicker.Current[2],
									Colorpicker.Current[3]
								)
							end
						elseif
							Colorpicker.Open
							and Colorpicker.Holder.Transparency
							and Colorpicker.Holding.Transparency
						then
							Colorpicker.Current[4] = 1
								- (
									Clamp(
										Monolith.MousePosition.X - Colorpicker.Holder.Transparency.Position.X,
										0,
										Colorpicker.Holder.Transparency.Size.X
									) / Colorpicker.Holder.Transparency.Size.X
								)
							--
							Colorpicker.Holder.Transparency_Cursor[1].Position =
								Menu:Position(1 - Colorpicker.Current[4], -3, 0, -3, Colorpicker.Holder.Transparency)
							Colorpicker.Holder.Transparency_Cursor[2].Position =
								Menu:Position(0, 1, 0, 1, Colorpicker.Holder.Transparency_Cursor[1])
							Colorpicker.Holder.Transparency_Cursor[3].Position =
								Menu:Position(0, 1, 0, 1, Colorpicker.Holder.Transparency_Cursor[2])
							Colorpicker.Holder.Transparency_Cursor[3].Color =
								Color3.fromHSV(0, 0, 1 - Colorpicker.Current[4])
							Frame.Transparency = (1 - Colorpicker.Current[4])
							--
							Menu:UpdateTransparency(Frame, (1 - Colorpicker.Current[4]))
							Menu:UpdateOffset(
								Colorpicker.Holder.Transparency_Cursor[1],
								{
									NewVector2(
										(Colorpicker.Holder.Transparency.Size.X * (1 - Colorpicker.Current[4])) - 3,
										-3
									),
									Colorpicker.Holder.Transparency,
								}
							)
							--
							Colorpicker.Holder.Background.Color = Color3.fromHSV(Colorpicker.Current[1], 1, 1)
						end
						--
						Colorpicker:Set(Colorpicker.Current)
						return self
					end
					--
					function Colorpicker:Get()
						return {
							Color = Color3.fromHSV(
								Colorpicker.Current[1],
								Colorpicker.Current[2],
								Colorpicker.Current[3]
							),
							Transparency = Colorpicker.Current[4],
						}
					end
					--
					Menu.Inputs.Began[#Menu.Inputs.Began + 1] = function(Input)
						if
							Input.UserInputType == Enum.UserInputType.MouseButton1
							and Window.IsVisible
							and Outline.Visible
						then
							if
								Colorpicker.Open
								and Colorpicker.Holder.Inline
								and Menu:MouseOverDrawing({
									Colorpicker.Holder.Inline.Position.X,
									Colorpicker.Holder.Inline.Position.Y,
									Colorpicker.Holder.Inline.Position.X + Colorpicker.Holder.Inline.Size.X,
									Colorpicker.Holder.Inline.Position.Y + Colorpicker.Holder.Inline.Size.Y,
								})
							then
								if
									Colorpicker.Holder.Picker
									and Menu:MouseOverDrawing({
										Colorpicker.Holder.Picker.Position.X - 2,
										Colorpicker.Holder.Picker.Position.Y - 2,
										Colorpicker.Holder.Picker.Position.X - 2 + Colorpicker.Holder.Picker.Size.X + 4,
										Colorpicker.Holder.Picker.Position.Y - 2 + Colorpicker.Holder.Picker.Size.Y + 4,
									})
								then
									Colorpicker.Holding.Picker = true
									Colorpicker:Refresh()
								elseif
									Colorpicker.Holder.Huepicker
									and Menu:MouseOverDrawing({
										Colorpicker.Holder.Huepicker.Position.X - 2,
										Colorpicker.Holder.Huepicker.Position.Y - 2,
										Colorpicker.Holder.Huepicker.Position.X
											- 2
											+ Colorpicker.Holder.Huepicker.Size.X
											+ 4,
										Colorpicker.Holder.Huepicker.Position.Y
											- 2
											+ Colorpicker.Holder.Huepicker.Size.Y
											+ 4,
									})
								then
									Colorpicker.Holding.Huepicker = true
									Colorpicker:Refresh()
								elseif
									Colorpicker.Holder.Transparency
									and Menu:MouseOverDrawing({
										Colorpicker.Holder.Transparency.Position.X - 2,
										Colorpicker.Holder.Transparency.Position.Y - 2,
										Colorpicker.Holder.Transparency.Position.X
											- 2
											+ Colorpicker.Holder.Transparency.Size.X
											+ 4,
										Colorpicker.Holder.Transparency.Position.Y
											- 2
											+ Colorpicker.Holder.Transparency.Size.Y
											+ 4,
									})
								then
									Colorpicker.Holding.Transparency = true
									Colorpicker:Refresh()
								end
							elseif
								Menu:MouseOverDrawing({
									Section.SectionOutline.Position.X
										+ (
											Section.SectionOutline.Size.X
											- (Colorpicker.Index == 0 and (30 + 4 + 2) or (54 + 4 + 2))
										),
									Section.SectionOutline.Position.Y + Colorpicker.Axis,
									Section.SectionOutline.Position.X
										+ Section.SectionOutline.Size.X
										- (Colorpicker.Index == 1 and 40 or 15),
									Section.SectionOutline.Position.Y + Colorpicker.Axis + 15,
								}) and not Window:IsOverContent()
							then
								if not Colorpicker.Open then
									Window:CloseContent()
									Colorpicker.Open = not Colorpicker.Open
									--
									local Outline = Menu:Create(
										"Frame",
										{ NewVector2(5, Colorpicker.Axis + 5), Section.SectionOutline },
										{
											Size = Menu:Size(0.9, -10, 0, Alpha and 172 or 163, Section.SectionOutline),
											Position = Menu:Position(
												0,
												5,
												0,
												Colorpicker.Axis + 5,
												Section.SectionOutline
											),
											Color = Theme.Colors.A,
										},
										Colorpicker.Holder.Drawings
									)
									Colorpicker.Holder.Inline = Outline
									--
									local Frame = Menu:Create("Frame", { NewVector2(1, 1), Outline }, {
										Size = Menu:Size(1, -2, 1, -2, Outline),
										Position = Menu:Position(0, 1, 0, 1, Outline),
										Color = Theme.Colors.C,
									}, Colorpicker.Holder.Drawings)
									--
									local PickerOutline = Menu:Create("Frame", { NewVector2(5, 5), Frame }, {
										Size = Menu:Size(1, -25, 1, Alpha and -25 or -10, Frame),
										Position = Menu:Position(0, 5, 0, 5, Frame),
										Color = Theme.Colors.A,
									}, Colorpicker.Holder.Drawings)
									--
									local PickerBg = Menu:Create("Frame", { NewVector2(1, 1), PickerOutline }, {
										Size = Menu:Size(1, -2, 1, -2, PickerOutline),
										Position = Menu:Position(0, 1, 0, 1, PickerOutline),
										Color = Color3.fromHSV(Colorpicker.Current[1], 1, 1),
									}, Colorpicker.Holder.Drawings)
									Colorpicker.Holder.Background = PickerBg
									--
									local PickerImage = Menu:Create("Image", { NewVector2(0, 0), PickerBg }, {
										Size = Menu:Size(1, 0, 1, 0, PickerBg),
										Position = Menu:Position(0, 0, 0, 0, PickerBg),
									}, Colorpicker.Holder.Drawings)
									Colorpicker.Holder.Picker = PickerImage
									--
									local PickerCursor = Menu:Create(
										"Image",
										{
											NewVector2(
												(PickerImage.Size.X * Colorpicker.Current[2]) - 3,
												(PickerImage.Size.Y * (1 - Colorpicker.Current[3])) - 3
											),
											PickerImage,
										},
										{
											Size = Menu:Size(0, 5, 0, 5, PickerImage),
											Position = Menu:Position(
												Colorpicker.Current[2],
												-3,
												1 - Colorpicker.Current[3],
												-3,
												PickerImage
											),
										},
										Colorpicker.Holder.Drawings
									)
									Colorpicker.Holder.Picker_Cursor = PickerCursor
									--
									local HueOutline = Menu:Create(
										"Frame",
										{ NewVector2(Frame.Size.X - 17, 5), Frame },
										{
											Size = Menu:Size(0, 12, 1, Alpha and -25 or -10, Frame),
											Position = Menu:Position(1, -17, 0, 5, Frame),
											Color = Theme.Colors.A,
										},
										Colorpicker.Holder.Drawings
									)
									--
									local HueImage = Menu:Create("Image", { NewVector2(1, 1), HueOutline }, {
										Size = Menu:Size(1, -2, 1, -2, HueOutline),
										Position = Menu:Position(0, 1, 0, 1, HueOutline),
									}, Colorpicker.Holder.Drawings)
									Colorpicker.Holder.Huepicker = HueImage
									--
									local CursorOutline = Menu:Create(
										"Frame",
										{ NewVector2(-3, (HueImage.Size.Y * Colorpicker.Current[1]) - 3), HueImage },
										{
											Size = Menu:Size(1, 6, 0, 6, HueImage),
											Position = Menu:Position(0, -3, Colorpicker.Current[1], -3, HueImage),
											Color = NewRGB(0, 0, 0),
										},
										Colorpicker.Holder.Drawings
									)
									Colorpicker.Holder.Huepicker_Cursor[1] = CursorOutline
									--
									local CursorInline = Menu:Create("Frame", { NewVector2(1, 1), CursorOutline }, {
										Size = Menu:Size(1, -2, 1, -2, CursorOutline),
										Position = Menu:Position(0, 1, 0, 1, CursorOutline),
										Color = NewRGB(255, 255, 255),
									}, Colorpicker.Holder.Drawings)
									Colorpicker.Holder.Huepicker_Cursor[2] = CursorInline
									--
									local CursorColor = Menu:Create("Frame", { NewVector2(1, 1), CursorInline }, {
										Size = Menu:Size(1, -2, 1, -2, CursorInline),
										Position = Menu:Position(0, 1, 0, 1, CursorInline),
										Color = Color3.fromHSV(Colorpicker.Current[1], 1, 1),
									}, Colorpicker.Holder.Drawings)
									Colorpicker.Holder.Huepicker_Cursor[3] = CursorColor
									--
									if Alpha then
										local TranspOutline = Menu:Create(
											"Frame",
											{ NewVector2(5, Frame.Size.X - 40), Frame },
											{
												Size = Menu:Size(1, -25, 0, 12, Frame),
												Position = Menu:Position(0, 5, 1, -17, Frame),
												Color = Theme.Colors.A,
											},
											Colorpicker.Holder.Drawings
										)
										--
										local TranspBg = Menu:Create("Frame", { NewVector2(1, 1), TranspOutline }, {
											Size = Menu:Size(1, -2, 1, -2, TranspOutline),
											Position = Menu:Position(0, 1, 0, 1, TranspOutline),
											Color = Color3.fromHSV(
												Colorpicker.Current[1],
												Colorpicker.Current[2],
												Colorpicker.Current[3]
											),
										}, Colorpicker.Holder.Drawings)
										Colorpicker.Holder.Transparencybg = TranspBg
										--
										local TranspImage = Menu:Create("Image", { NewVector2(1, 1), TranspOutline }, {
											Size = Menu:Size(1, -2, 1, -2, TranspOutline),
											Position = Menu:Position(0, 1, 0, 1, TranspOutline),
										}, Colorpicker.Holder.Drawings)
										Colorpicker.Holder.Transparency = TranspImage
										--
										local CursorOutline = Menu:Create(
											"Frame",
											{
												NewVector2((TranspImage.Size.X * (1 - Colorpicker.Current[4])) - 3, -3),
												TranspImage,
											},
											{
												Size = Menu:Size(0, 6, 1, 6, TranspImage),
												Position = Menu:Position(
													1 - Colorpicker.Current[4],
													-3,
													0,
													-3,
													TranspImage
												),
												Color = NewRGB(0, 0, 0),
											},
											Colorpicker.Holder.Drawings
										)
										Colorpicker.Holder.Transparency_Cursor[1] = CursorOutline
										--
										local CursorInline = Menu:Create("Frame", { NewVector2(1, 1), CursorOutline }, {
											Size = Menu:Size(1, -2, 1, -2, CursorOutline),
											Position = Menu:Position(0, 1, 0, 1, CursorOutline),
											Color = NewRGB(255, 255, 255),
										}, Colorpicker.Holder.Drawings)
										Colorpicker.Holder.Transparency_Cursor[2] = CursorInline
										--
										local CursorColor = Menu:Create("Frame", { NewVector2(1, 1), CursorInline }, {
											Size = Menu:Size(1, -2, 1, -2, CursorInline),
											Position = Menu:Position(0, 1, 0, 1, CursorInline),
											Color = Color3.fromHSV(0, 0, 1 - Colorpicker.Current[4]),
										}, Colorpicker.Holder.Drawings)
										Colorpicker.Holder.Transparency_Cursor[3] = CursorColor
										--
										Menu:LoadImage(TranspImage, "Transparency")
									end
									--
									Menu:LoadImage(PickerImage, "Valsat")
									Menu:LoadImage(PickerCursor, "Valsat_Cursor")
									Menu:LoadImage(HueImage, "Hue")
									--
									Window.CurrentContent.Frame = Outline
									Window.CurrentContent.Colorpicker = Colorpicker
								else
									Colorpicker.Open = not Colorpicker.Open
									--
									for _, Drawing in next, Colorpicker.Holder.Drawings do
										Menu:Remove(Drawing)
									end
									--
									Colorpicker.Holder.Drawings = {}
									Colorpicker.Holder.Inline = nil
									--
									Window.CurrentContent.Frame = nil
									Window.CurrentContent.Colorpicker = nil
								end
							else
								if Colorpicker.Open then
									Colorpicker.Open = not Colorpicker.Open
									--
									for _, Drawing in next, Colorpicker.Holder.Drawings do
										Menu:Remove(Drawing)
									end
									--
									Colorpicker.Holder.Drawings = {}
									Colorpicker.Holder.Inline = nil
									--
									Window.CurrentContent.Frame = nil
									Window.CurrentContent.Colorpicker = nil
								end
							end
						elseif Input.UserInputType == Enum.UserInputType.MouseButton1 and Colorpicker.Open then
							Colorpicker.Open = not Colorpicker.Open
							--
							for _, Drawing in next, Colorpicker.Holder.Drawings do
								Menu:Remove(Drawing)
							end
							--
							Colorpicker.Holder.Drawings = {}
							Colorpicker.Holder.Inline = nil
							--
							Window.CurrentContent.Frame = nil
							Window.CurrentContent.Colorpicker = nil
						end
					end
					--
					Menu.Inputs.Ended[#Menu.Inputs.Ended + 1] = function(Input)
						if Input.UserInputType == Enum.UserInputType.MouseButton1 then
							if Colorpicker.Holding.Picker then
								Colorpicker.Holding.Picker = not Colorpicker.Holding.Picker
							end
							if Colorpicker.Holding.Huepicker then
								Colorpicker.Holding.Huepicker = not Colorpicker.Holding.Huepicker
							end
							if Colorpicker.Holding.Transparency then
								Colorpicker.Holding.Transparency = not Colorpicker.Holding.Transparency
							end
						end
					end
					--
					Menu.Inputs.Changed[#Menu.Inputs.Changed + 1] = function()
						if
							Colorpicker.Open and Colorpicker.Holding.Picker
							or Colorpicker.Holding.Huepicker
							or Colorpicker.Holding.Transparency
						then
							if Window.IsVisible then
								Colorpicker:Refresh()
							else
								if Colorpicker.Holding.Picker then
									Colorpicker.Holding.Picker = not Colorpicker.Holding.Picker
								end
								if Colorpicker.Holding.Huepicker then
									Colorpicker.Holding.Huepicker = not Colorpicker.Holding.Huepicker
								end
								if Colorpicker.Holding.Transparency then
									Colorpicker.Holding.Transparency = not Colorpicker.Holding.Transparency
								end
							end
						end
					end
					--
					if Flag and tostring(Flag) ~= "" and tostring(Flag) ~= " " and not Menu.Flags[tostring(Flag)] then
						Menu.Flags[tostring(Flag)] = Colorpicker
					end
					--
					Toggle.AddedAxis = Toggle.AddedAxis + 30 + 4 + 2
					Toggle.Colorpickers = Toggle.Colorpickers + 1
					Section:Update()
					--
					return Toggle, Colorpicker
				end
				--
				function Toggle:Keybind(Info)
					local Info = Info or {}
					local Def = Info.default or Info.Default or nil
					local Flag = Info.flag or Info.Flag or nil
					local Mode = Info.mode or Info.Mode or "Toggle"
					local Ignore = Info.Ignore or Info.ignore or false
					local KeybindName = Info.Keybind_name or Info.KeybindName or "Key Name"
					local Callback = Info.Callback or Info.Callback or function() end
					local Changed = Info.changed or Info.Changed or function() end
					--
					local Keybind = {
						KeybindName = KeybindName or Name,
						Axis = Toggle.Axis,
						Current = {},
						Selecting = false,
						Mode = Mode,
						Open = false,
						ModeMenu = { Buttons = {}, Drawings = {} },
