						"C",
						"V",
						"B",
						"N",
						"M",
						"One",
						"Two",
						"Three",
						"Four",
						"Five",
						"Six",
						"Seveen",
						"Eight",
						"Nine",
						"Zero",
						"F1",
						"F2",
						"F3",
						"F4",
						"F5",
						"F6",
						"F7",
