						"Semicolon",
						"Period",
						"Comma",
						"Quote",
						"LeftBracket",
						"RightBracket",
					}
					local AllowedInputTypes = { "MouseButton1", "MouseButton2", "MouseButton3" }
					local ShortenedInputs = {
						["MouseButton1"] = "MB1",
						["MouseButton2"] = "MB2",
						["MouseButton3"] = "MB3",
						["Insert"] = "Ins",
						["LeftAlt"] = "LAlt",
						["LeftControl"] = "LCtrl",
						["LeftShift"] = "LShift",
						["RightAlt"] = "RAlt",
						["RightControl"] = "RCtrl",
						["RightShift"] = "RShift",
						["CapsLock"] = "Caps",
					}
					--
					local KeybindOutline = Menu:Create(
						"Frame",
						{
							NewVector2(Section.SectionOutline.Size.X - (53 + 4), Keybind.Axis - 1),
							Section.SectionOutline,
						},
						{
							Size = Menu:Size(0, 40, 0, 12),
							Position = Menu:Position(1, -(53 + 4), 0, Keybind.Axis - 1, Section.SectionOutline),
							Color = Theme.Colors.A,
							Visible = Tab.Open,
						},
						Section.VisibleContent
					)
					--
					local KeybindFill = Menu:Create("Frame", { NewVector2(1, 1), KeybindOutline }, {
						Size = Menu:Size(1, -2, 1, -2, KeybindOutline),
						Position = Menu:Position(0, 1, 0, 1, KeybindOutline),
						Color = Theme.Colors.C,
						Visible = Tab.Open,
					}, Section.VisibleContent)
					--
					local KeybindValue = Menu:Create(
						"TextLabel",
						{ NewVector2(KeybindOutline.Size.X / 2, 2), KeybindOutline },
						{
							Text = "-",
							Size = Theme.Text.Size,
							Font = Theme.Text.Font,
							Color = Theme.Text.Color,
							OutlineColor = Theme.Text.Outline,
							Center = true,
							Position = Menu:Position(0.5, 0, 0, 2, KeybindOutline),
							Visible = Tab.Open,
						},
						Section.VisibleContent
					)
					--
					function Keybind:Shorten(String)
						for Index, Value in next, ShortenedInputs do
							String = Gsub(String, Index, Value)
						end
						--
						return String
					end
					--
					function Keybind:Change(Input)
						Input = Input or "-"
						local InputTable = {}
						--
						if not Input or Input.Name == "Backspace" then
							Keybind.Current = {}
							KeybindValue.Text = "-"
							Changed(Keybind.Current)
							--
							return true
						end
						--
						if Input.EnumType then
							if Input.EnumType == Enum.KeyCode or Input.EnumType == Enum.UserInputType then
								if Find(AllowedKeyCodes, Input.Name) or Find(AllowedInputTypes, Input.Name) then
									InputTable =
										{ Input.EnumType == Enum.KeyCode and "KeyCode" or "UserInputType", Input.Name }
									--
									Keybind.Current = InputTable
									KeybindValue.Text = #Keybind.Current > 0 and Keybind:Shorten(Keybind.Current[2])
										or "-"
									--
									Changed(Keybind.Current)
									return true
								end
							end
						end
						--
						return false
					end
					--
					function Keybind:Get()
						return Keybind.Current
					end
					--
					function Keybind:SetActive(Bool)
						Keybind.Active = Bool
					end
					--
					function Keybind:Set(Table)
						Keybind.Current = Table.Key
						Keybind.Mode = Table.Mode or "Always"
						KeybindValue.Text = #Keybind.Current > 0 and Keybind:Shorten(Keybind.Current[2]) or "-"

						Keybind.Active = Keybind.Mode == "Always" and true or false
					end
					--
					function Keybind:Set_Callback(P_Callback)
						Callback = P_Callback
						Callback(self:Get())
					end
					--
					function Keybind:IsActive()
						return Keybind.Active
					end
					--
					function Keybind:Reset()
						for i, v in next, Keybind.ModeMenu.Buttons do
							v.Transparency = v.Text == Keybind.Mode and 1 or 0.5
						end
						--
						Keybind.Active = Keybind.Mode == "Always" and true or false
						if Keybind.Current[1] and Keybind.Current[2] then
							Monolith:Notify(
								"NotifyWhite",
								string.format("%s : %s", Keybind.KeybindName, tostring(Keybind.Active)),
								Flags["Keybind Notify Lifetime"]:Get()
							)
							Callback(Enum[Keybind.Current[1]][Keybind.Current[2]], Keybind.Active)
						end
					end
					--
					Keybind:Change(Def)
					--
					Menu.Inputs.Began[#Menu.Inputs.Began + 1] = function(Input)
						if Keybind.Current[1] and Keybind.Current[2] then
							if
								Input.KeyCode == Enum[Keybind.Current[1]][Keybind.Current[2]]
								or Input.UserInputType == Enum[Keybind.Current[1]][Keybind.Current[2]]
							then
								if Keybind.Mode == "Hold" then
									local Old = Keybind.Active
									Keybind.Active = Toggle:Get()
									if Keybind.Active then
										Window.KeybindsList:Add(KeybindName, KeybindValue.Text)
									else
										Window.KeybindsList:Remove(KeybindName)
									end
									if Keybind.Active ~= Old then
										Callback(Enum[Keybind.Current[1]][Keybind.Current[2]], Keybind.Active)
									end
								elseif Keybind.Mode == "Toggle" then
									local Old = Keybind.Active
									Keybind.Active = not Keybind.Active == true and Toggle:Get() or false
									if Keybind.Active then
										Window.KeybindsList:Add(KeybindName, KeybindValue.Text)
									else
										Window.KeybindsList:Remove(KeybindName)
									end
									if Keybind.Active ~= Old then
										Callback(Enum[Keybind.Current[1]][Keybind.Current[2]], Keybind.Active)
									end
								end
							end
						end
						--
						if Keybind.Selecting and Window.IsVisible then
							local Done =
								Keybind:Change(Input.KeyCode.Name ~= "Unknown" and Input.KeyCode or Input.UserInputType)
							if Done then
								Keybind.Selecting = false
								Keybind.Active = Keybind.Mode == "Always" and true or false
								KeybindFill.Color = Theme.Colors.C
								--
								Window.KeybindsList:Remove(KeybindName)
								Callback(Enum[Keybind.Current[1]][Keybind.Current[2]], Keybind.Active)
							end
						end
						--
						if not Window.IsVisible and Keybind.Selecting then
							Keybind.Selecting = false
							KeybindFill.Color = Theme.Colors.E
						end
						--
						if
							Input.UserInputType == Enum.UserInputType.MouseButton1
							and Window.IsVisible
							and KeybindOutline.Visible
						then
							if
								Menu:MouseOverDrawing({
									Section.SectionOutline.Position.X + (Section.SectionOutline.Size.X - (54 + 4 + 2)),
									Section.SectionOutline.Position.Y + Keybind.Axis,
									Section.SectionOutline.Position.X + Section.SectionOutline.Size.X - 15,
									Section.SectionOutline.Position.Y + Keybind.Axis + 14,
								})
								and not Window:IsOverContent()
								and not Keybind.Selecting
							then
								Keybind.Selecting = true
								KeybindFill.Color = Theme.Colors.E
							end
							--
							if Keybind.Open and Keybind.ModeMenu.Frame then
								if
									Menu:MouseOverDrawing({
										Keybind.ModeMenu.Frame.Position.X,
										Keybind.ModeMenu.Frame.Position.Y,
										Keybind.ModeMenu.Frame.Position.X + Keybind.ModeMenu.Frame.Size.X,
										Keybind.ModeMenu.Frame.Position.Y + Keybind.ModeMenu.Frame.Size.Y,
									})
								then
									local Changed = false
									--
									for Index, Value in next, Keybind.ModeMenu.Buttons do
										if
											Menu:MouseOverDrawing({
												Keybind.ModeMenu.Frame.Position.X,
												Keybind.ModeMenu.Frame.Position.Y + (15 * (Index - 1)),
												Keybind.ModeMenu.Frame.Position.X + Keybind.ModeMenu.Frame.Size.X,
												Keybind.ModeMenu.Frame.Position.Y + (15 * (Index - 1)) + 15,
											})
										then
											Keybind.Mode = Value.Text
											Changed = true
										end
									end
									--
									if Changed then
										Keybind:Reset()
									end
								else
									Keybind.Open = not Keybind.Open
									--
									for Index, Drawing in next, Keybind.ModeMenu.Drawings do
										Menu:Remove(Drawing)
									end
									--
									Keybind.ModeMenu.Drawings = {}
									Keybind.ModeMenu.Buttons = {}
									Keybind.ModeMenu.Frame = nil
									--
									Window.CurrentContent.Frame = nil
									Window.CurrentContent.Keybind = nil
								end
							end
						end
						--
						if
							Input.UserInputType == Enum.UserInputType.MouseButton2
							and Window.IsVisible
							and KeybindOutline.Visible
						then
							if
								Menu:MouseOverDrawing({
									Section.SectionOutline.Position.X + (Section.SectionOutline.Size.X - (54 + 4 + 2)),
									Section.SectionOutline.Position.Y + Keybind.Axis,
									Section.SectionOutline.Position.X + Section.SectionOutline.Size.X,
									Section.SectionOutline.Position.Y + Keybind.Axis + 17,
								})
								and not Window:IsOverContent()
								and not Keybind.Selecting
							then
								Window:CloseContent()
								Keybind.Open = not Keybind.Open
								--
								local ModeMenu = Menu:Create(
									"Frame",
									{ NewVector2(KeybindOutline.Size.X + 1, 0), KeybindOutline },
									{
										Size = Menu:Size(0, 64, 0, 49),
										Position = Menu:Position(1, 1, 0, 0, KeybindOutline),
										Color = Theme.Colors.A,
										Visible = Tab.Open,
									},
									Keybind.ModeMenu.Drawings
								)
								Keybind.ModeMenu.Frame = ModeMenu
								--
								local ModeMenu_Frame = Menu:Create("Frame", { NewVector2(1, 1), ModeMenu }, {
									Size = Menu:Size(1, -2, 1, -2, ModeMenu),
									Position = Menu:Position(0, 1, 0, 1, ModeMenu),
									Color = Theme.Colors.C,
									Visible = Tab.Open,
								}, Keybind.ModeMenu.Drawings)
								--
								local ModeMenuGradient = Menu:Create("Image", { NewVector2(1, 1), ModeMenu }, {
									Position = Menu:Position(0, 1, 0, 1, ModeMenu),
									Size = Menu:Size(1, -2, 1, -2, ModeMenu),
									Visible = Tab.Open,
									ZIndex = 9998,
								}, Keybind.ModeMenu.Drawings)
								--
								for Index, Value in next, { "Always", "Toggle", "Hold" } do
									local Button_Text = Menu:Create(
										"TextLabel",
										{ NewVector2(ModeMenu_Frame.Size.X / 2, 15 * (Index - 1)), ModeMenu_Frame },
										{
											Text = Value,
											Size = Theme.Text.Size,
											Font = Theme.Text.Font,
											Color = Theme.Text.Color,
											Transparency = Value == Keybind.Mode and 1 or 0.5,
											ZIndex = 9999,
											Center = true,
											OutlineColor = Theme.Text.Outline,
											Position = Menu:Position(0.5, 0, 0, 15 * (Index - 1), ModeMenu_Frame),
											Visible = Tab.Open,
										},
										Keybind.ModeMenu.Drawings
									)
									Keybind.ModeMenu.Buttons[#Keybind.ModeMenu.Buttons + 1] = Button_Text
								end
								--
								Menu:LoadImage(ModeMenuGradient, "Gradient")
								--
								Window.CurrentContent.Frame = ModeMenu
								Window.CurrentContent.Keybind = Keybind
							end
						end
					end
					--
					Menu.Inputs.Ended[#Menu.Inputs.Ended + 1] = function(Input)
						if Keybind.Active and Keybind.Mode == "Hold" then
							if Keybind.Current[1] and Keybind.Current[2] then
								if
									Input.KeyCode == Enum[Keybind.Current[1]][Keybind.Current[2]]
									or Input.UserInputType == Enum[Keybind.Current[1]][Keybind.Current[2]]
								then
									Keybind.Active = false
									Window.KeybindsList:Remove(KeybindName)
									Callback(Enum[Keybind.Current[1]][Keybind.Current[2]], Keybind.Active)
								end
							end
						end
					end
					--
					if Flag and tostring(Flag) ~= "" and tostring(Flag) ~= " " and not Menu.Flags[tostring(Flag)] then
						Menu.Flags[tostring(Flag)] = Keybind
					end
					--
					Keybind.Active = Keybind.Mode == "Always" and true or false
					--
					Toggle.AddedAxis = 53 + 4 + 2
					Section:Update()
					--
					return Toggle, Keybind
				end
				--
				return Toggle
			end
			--
			function Menu.Sections:Slider(Info)
				-- Info
				local Info = Info or {}
				local Name = Info.Name or Info.name or "new slider"
				local Def = Info.Def or Info.def or Info.Default or Info.default or 10
				local Min = Info.Min or Info.min or Info.Minimum or Info.minimum or 0
				local Max = Info.Max or Info.max or Info.Maximum or Info.maximum or 100
				local Sub = Info.Prefix or Info.prefix or Info.Measurement or Info.measurement or ""
				local Decimals = Info.Decimals or Info.decimals or 1
				local Length = Info.Length or Info.length or 0.34
				local Flag = Info.Flag or Info.flag or nil
				local Callback = Info.Callback or Info.callback or function() end
				Decimals = 1 / Decimals
				Def = Clamp(Def, Min, Max)

				-- Variables
				local Window = self.Window
				local Tab = self.Tab
				local Section = self
				local Slider = {
					Min = Min,
					Max = Max,
					Sub = Sub,
					Decimals = Decimals,
					Axis = Section.CurrentAxis,
					Current = Def,
					Holding = false,
				}

				do -- Drawings
					local TextBounds = Menu:GetTextBounds(Name, Theme.Text.Size, Theme.Text.Font)

					local Outline = Menu:Create("Frame", { NewVector2(10, Slider.Axis + 5), Section.SectionOutline }, {
						Position = Menu:Position(0, 10, 0, Slider.Axis + 5, Section.SectionOutline),
						Size = Menu:Size(Length, 0, 0, 5, Section.SectionOutline),
						Color = Theme.Colors.A,
						Visible = Tab.Open,
					}, Section.VisibleContent)
					Slider["Outline"] = Outline

					local Inline = Menu:Create("Frame", { NewVector2(1, 1), Outline }, {
						Position = Menu:Position(0, 1, 0, 1, Outline),
						Size = Menu:Size(1, -2, 1, -2, Outline),
						Color = Theme.Colors.Accent,
						Visible = Tab.Open,
					}, Section.VisibleContent)
					Slider["Inline"] = Inline

					local Gradient = Menu:Create("Image", { NewVector2(0, 0), Inline }, {
						Position = Menu:Position(1, 0, 1, 0, Inline),
						Size = Menu:Size(1, 1, 1, 0, Inline),
						Visible = Tab.Open,
					}, Section.VisibleContent)

					local BarOutline = Menu:Create("Frame", { NewVector2(1, -3), Inline }, {
						Size = Menu:Size(0, 4, 1, 6, Inline),
						Position = Menu:Position(0, 1, 0, -3, Inline),
						Color = Theme.Colors.A,
						Visible = Tab.Open,
					}, Section.VisibleContent)
					Slider["BarOutline"] = BarOutline

					local BarInline = Menu:Create("Frame", { NewVector2(1, 1), BarOutline }, {
						Position = Menu:Position(0, 1, 0, 1, BarOutline),
						Size = Menu:Size(1, -2, 1, -2, BarOutline),
						Color = Theme.Colors.Accent,
						Visible = Tab.Open,
					}, Section.VisibleContent)
					Slider["BarInline"] = BarInline -- change naming

					local Value = Menu:Create("TextLabel", { NewVector2(Outline.Size.X + 8, -3), Outline }, {
						Position = Menu:Position(1, 0, 1, -3, Outline),
						Text = Format("%s %s", Name, Slider.Current .. Slider.Sub),
						OutlineColor = Theme.Text.Outline,
						Color = Theme.Text.Color,
						Size = Theme.Text.Size,
						Font = Theme.Text.Font,
						Center = false,
						Visible = Tab.Open,
					}, Section.VisibleContent)
					Slider["Value"] = Value

					Menu:LoadImage(Gradient, "GradientRight")
				end

				do -- Functions
					function Slider:Set(Value, Force) -- FORCE: stupid fix for SliderSlide positioning, fixes the default value -- todo remove force and move it under slider:set!
						local OldValue = Slider.Current

						Slider.Current = Clamp(Round(Value * Slider.Decimals) / Slider.Decimals, Slider.Min, Slider.Max)

						if Slider.Current ~= OldValue or Force then -- or Force
							local Percent = 1 - ((Slider.Max - Slider.Current) / (Slider.Max - Slider.Min))

							Slider["Value"].Text = Format("%s %s", Name, Slider.Current .. Slider.Sub)

							if not Force then
								Menu:Lerp(
									Slider["BarOutline"],
									{ Position = Menu:Position(Percent, -2, 0, -3, Slider["Inline"]) },
									0.08
								)
								Menu:Lerp(
									Slider["BarInline"],
									{ Position = Menu:Position(Percent, -1, 0, -2, Slider["Inline"]) },
									0.08
								)
							else
								Slider["BarOutline"].Position = Menu:Position(Percent, -2, 0, -3, Slider["Inline"])
								Slider["BarInline"].Position = Menu:Position(0, 1, 0, 1, Slider["BarOutline"])
							end

							Menu:UpdateOffset(
								Slider["BarOutline"],
								{ NewVector2((Slider["Inline"].Size.X * Percent) - 3, -3), Slider["Inline"] }
							)

							if not Force then
								Callback(Slider.Current)
							end
						end
					end

					function Slider:Set_Callback(P_Callback)
						Callback = P_Callback
						Callback(self:Get())
					end

					function Slider:Refresh()
						local Percent = Clamp(
							Monolith.MousePosition.X - Slider["Inline"].Position.X,
							0,
							Slider["Inline"].Size.X
						) / Slider["Inline"].Size.X
						local Value = Floor((Slider.Min + (Slider.Max - Slider.Min) * Percent) * Slider.Decimals)
							/ Slider.Decimals
						Value = Clamp(Value, Slider.Min, Slider.Max)
						Slider:Set(Value)
					end

					function Slider:Get()
						return Slider.Current
					end

					Slider:Set(Def, true)
				end

				do -- Connections (Input)
					Menu.Inputs.Began[#Menu.Inputs.Began + 1] = function(Input)
						if
							Input.UserInputType == Enum.UserInputType.MouseButton1
							and Window.IsVisible
							and Tab.Open
							and Slider["Outline"].Visible
							and not Window:IsOverContent()
							and Menu:MouseOverDrawing({
								Section.SectionOutline.Position.X + 10,
								Section.SectionOutline.Position.Y + Slider.Axis,
								Section.SectionOutline.Position.X + Section.SectionOutline.Size.X - 15,
								Section.SectionOutline.Position.Y + Slider.Axis + 16,
							})
						then
							Slider.Holding = true
							Slider:Refresh()
						end
					end
					--
					Menu.Inputs.Ended[#Menu.Inputs.Ended + 1] = function(Input)
						if
							Input.UserInputType == Enum.UserInputType.MouseButton1
							and Window.IsVisible
							and Slider.Holding
						then
							Slider.Holding = false
						end
					end
					--
					Menu.Inputs.Changed[#Menu.Inputs.Changed + 1] = function(Input)
						if Window.IsVisible and Slider.Holding then
							Slider:Refresh()
						end
					end
				end

				if Flag and tostring(Flag) ~= "" and tostring(Flag) ~= " " and not Flags[tostring(Flag)] then
					Flags[tostring(Flag)] = Slider
				end

				Section.CurrentAxis = Section.CurrentAxis + 20
				Section:Update()

				return Slider
			end
			--
			function Menu.Sections:Dropdown(Info)
				local Info = Info or {}
				local Name = Info.Name or Info.name or "new dropdown"
				local Options = Info.Options or Info.options or { "Monolith", ".", "wtf" }
				local Multi = Info.Multi or Info.multi or false
				local Min = Info.Minimum or Info.Min or Info.minimum or Info.min or 1
				local Length = Info.Length or Info.length or 0.5
				local Def = Info.Default or Info.default or Options[1]
				local Flag = Info.Flag or Info.flag or nil
				local Callback = Info.Callback or Info.callback or function() end
				--
				local Window = self.Window
				local Tab = self.Tab
				local Section = self
				--
				local Dropdown = {
					Open = false,
					Multi = Multi,
					Current = Multi and Def or tostring(Def),
					Options = Options,
					Holder = { Buttons = {}, Drawings = {} },
					Axis = Section.CurrentAxis,
				}
				--
				local DropdownOutline = Menu:Create(
					"Frame",
					{ NewVector2(10, Dropdown.Axis), Section.SectionOutline },
					{
						Size = Menu:Size(Length, 0, 0, 16, Section.SectionOutline),
						Position = Menu:Position(0, 10, 0, Dropdown.Axis, Section.SectionOutline),
						Color = Theme.Colors.A,
						Visible = Tab.Open,
					},
					Section.VisibleContent
				)
				--
				local DropdownInline = Menu:Create("Frame", { NewVector2(1, 1), DropdownOutline }, {
					Size = Menu:Size(1, -2, 1, -2, DropdownOutline),
					Position = Menu:Position(0, 1, 0, 1, DropdownOutline),
					Color = Theme.Colors.F,
					Visible = Tab.Open,
				}, Section.VisibleContent)
				--
				local DropdownGradient = Menu:Create("Image", { NewVector2(1, 1), DropdownOutline }, {
					Position = Menu:Position(0, 1, 0, 1, DropdownOutline),
					Size = Menu:Size(1, -2, 1, -2, DropdownOutline),
					Visible = Tab.Open,
				}, Section.VisibleContent)
				--
				Menu:LoadImage(DropdownGradient, "GradientStrong")
				--
				local DropdownText = Menu:Create(
					"TextLabel",
					{ NewVector2(DropdownOutline.Size.X + 8, DropdownOutline.Size.Y / 2 - 5), DropdownOutline },
					{
						Text = Name,
						Size = Theme.Text.Size,
						Font = Theme.Text.Font,
						Color = Theme.Text.Color,
						OutlineColor = Theme.Text.Outline,
						Position = Menu:Position(1, 0, 1, (DropdownOutline.Size.Y / 2), DropdownOutline),
						Visible = Tab.Open,
					},
					Section.VisibleContent
				)
				--
				local DropdownValue = Menu:Create(
					"TextLabel",
					{ NewVector2(6, DropdownOutline.Size.Y / 2 - 5), DropdownOutline },
					{
						Text = Dropdown.Multi and "" or Dropdown.Current,
						Size = Theme.Text.Size,
						Font = Theme.Text.Font,
						Color = Theme.Text.Color,
						OutlineColor = Theme.Text.Outline,
						Position = Menu:Position(0, 6, 0, (DropdownOutline.Size.Y / 2) - 7, DropdownOutline),
						Visible = Tab.Open,
					},
					Section.VisibleContent
				)
				--
				local DropdownImage = Menu:Create(
					"Image",
					{ NewVector2(DropdownOutline.Size.X - 14, DropdownOutline.Size.Y / 2 - 4), DropdownOutline },
					{
						Size = Menu:Size(0, 11, 0, 8, DropdownOutline),
						Position = Menu:Position(1, -14, 0.5, -4, DropdownOutline),
						Visible = Tab.Open,
					},
					Section.VisibleContent
				)
				--
				Menu:LoadImage(DropdownImage, "ArrowDown")
				--
				function Dropdown:Update()
					if Dropdown.Open and Dropdown.Holder.Inline then -- this is old and shit
						for i, v in next, Dropdown.Holder.Buttons do
							if not Dropdowm.Multi then
								local Value = Dropdown.Options[i]
								--
								v[1].Text = Value
								v[1].Color = Value == tostring(Dropdown.Current) and Theme.Colors.Accent
									or Theme.Text.Color
								v[1].Position =
									Menu:Position(0, Value == tostring(Dropdown.Current) and 8 or 6, 0, 2, v[2])
								Menu:UpdateOffset(
									v[1],
									{ NewVector2(v[1].Text == tostring(Dropdown.Current) and 8 or 6, 2), v[2] }
								)
							else
								v[1].Color = Find(Dropdown.Current, v[1].Text) and Theme.Colors.Accent
									or Theme.Text.Color
								v[1].Position =
									Menu:Position(0, Find(Dropdown.Current, v[1].Text) and 8 or 6, 0, 2, v[2])
								--
								Menu:UpdateOffset(
									v[1],
									{ NewVector2(Find(Dropdown.Current, v[1].Text) and 8 or 6, 2), v[2] }
								)
							end
						end
					end
				end
				--
				function Dropdown:Set(Value)
					if typeof(Value) == "string" and Find(Options, Value) then
						Dropdown.Current = Value
						DropdownValue.Text = Value
						--
						Spawn(Callback, Dropdown.Current)
					elseif typeof(Value) == "table" then
						Dropdown.Options = Value
					end
				end
				--
				function Dropdown:Serialize(Table)
					local String = ""
					--
					for _, Value in next, Table do
						String = String .. Value .. ", "
					end
					--
					return Sub(String, 0, #String - 2)
				end
				--
				function Dropdown:Resort(Table, Original)
					local NewTable = {}
					--
					for _, Value in next, Original do
						if Find(Table, Value) then
							NewTable[#NewTable + 1] = Value
						end
					end
					--
					return NewTable
				end
				--
				function Dropdown:Add(Value)
					Insert(Options, tostring(Value))
				end
				--
				function Dropdown:Set_Callback(P_Callback)
					Callback = P_Callback
					Callback(self:Get())
				end
				--
				function Dropdown:Get()
					return Dropdown.Current
				end
				--
				if Dropdown.Multi then
					DropdownValue.Text = Menu:WrapText(
						Dropdown:Serialize(Dropdown:Resort(Dropdown.Current, Options)),
						DropdownOutline.Size.X - 10
					)
				end
				--
				Menu.Inputs.Began[#Menu.Inputs.Began + 1] = function(Input)
					if
						Input.UserInputType == Enum.UserInputType.MouseButton1
						and Window.IsVisible
						and DropdownOutline.Visible
					then
						if
							Dropdown.Open
							and Dropdown.Holder.Inline
							and Menu:MouseOverDrawing({
								Dropdown.Holder.Inline.Position.X,
								Dropdown.Holder.Inline.Position.Y,
								Dropdown.Holder.Inline.Position.X + Dropdown.Holder.Inline.Size.X,
								Dropdown.Holder.Inline.Position.Y + Dropdown.Holder.Inline.Size.Y,
							})
						then
							for i, v in next, Dropdown.Holder.Buttons do
								local Value = Dropdown.Options[i]
								--
								if
									Menu:MouseOverDrawing({
										v[2].Position.X,
										v[2].Position.Y,
										v[2].Position.X + v[2].Size.X,
										v[2].Position.Y + v[2].Size.Y,
									}) and v[1].Text ~= Dropdown.Current
								then
									if Dropdown.Multi then
										if not Find(Dropdown.Current, v[1].Text) then
											Dropdown.Current[#Dropdown.Current + 1] = v[1].Text
											--
											Menu:Lerp(v[1], { Transparency = 1 }, 0.25)
											Menu:UpdateTransparency(v[1], 1)

											--
											DropdownValue.Text = Menu:WrapText(
												Dropdown:Serialize(Dropdown:Resort(Dropdown.Current, Options)),
												DropdownOutline.Size.X - 10
											)
											Callback(Value)
											Dropdown:Update()
										else
											if #Dropdown.Current > Min then
												Remove(Dropdown.Current, Find(Dropdown.Current, v[1].Text))
												--
												Menu:Lerp(v[1], { Transparency = 0.25 }, 0.25)
												Menu:UpdateTransparency(v[1], 0.25)

												DropdownValue.Text = Menu:WrapText(
													Dropdown:Serialize(Dropdown:Resort(Dropdown.Current, Options)),
													DropdownOutline.Size.X - 10
												)
												Callback(Value)
												Dropdown:Update()
											end
										end
									else
										Menu:Lerp(v[1], { Transparency = 1 }, 0.25)
										Dropdown.Current = Value
										--
										for i2, v2 in next, Dropdown.Holder.Buttons do
											if v2[1].Text ~= Dropdown.Current and v2[1].Transparency ~= 0.25 then
												Menu:Lerp(v2[1], { Transparency = 0.25 }, 0.25)
											end
										end
										--
										DropdownValue.Text = Dropdown.Current
										Callback(Value)
										Dropdown:Update()
									end
								end
							end
						elseif
							Menu:MouseOverDrawing({
								Section.SectionOutline.Position.X,
								Section.SectionOutline.Position.Y + Dropdown.Axis,
								Section.SectionOutline.Position.X + Section.SectionOutline.Size.X,
								Section.SectionOutline.Position.Y + Dropdown.Axis + 18,
							}) and not Window:IsOverContent()
						then
							if not Dropdown.Open then
								Window:CloseContent()
								Dropdown.Open = not Dropdown.Open
								Menu:LoadImage(DropdownImage, "ArrowUp")
								--
								local OpenInline = Menu:Create("Frame", { NewVector2(0, 16), DropdownOutline }, {
									Size = Menu:Size(1, 0, 0, (#Dropdown.Options * 19), DropdownOutline),
									Position = Menu:Position(0, 0, 0, 16, DropdownOutline),
									Color = Theme.Colors.A,
									Visible = Tab.Open,
								}, Dropdown.Holder.Drawings)
								Dropdown.Holder["Inline"] = OpenInline
								--
								local OpenGradient = Menu:Create("Image", { NewVector2(1, 1), OpenInline }, {
									Position = Menu:Position(0, 1, 0, 1, OpenInline),
									Size = Menu:Size(1, -2, 1, -2, OpenInline),
									Visible = Tab.Open,
									ZIndex = 9998,
								}, Dropdown.Holder.Drawings)
								--
								for Index = 1, #Dropdown.Options do
									local Value = Dropdown.Options[Index]
									--
									if Value then
										--local Offset = (Dropdown.Multi and Find(Dropdown.Current, Value) and 8 or 6) or (Value == tostring(Dropdown.Current) and 8 or 6)
										local Transp = (
											Dropdown.Multi and (Find(Dropdown.Current, Value) and 1 or 0.25)
										) or (Value == tostring(Dropdown.Current) and 1 or 0.25)
										--
										local ValueFrame = Menu:Create(
											"Frame",
											{ NewVector2(1, (19 * (Index - 1))), OpenInline },
											{
												Size = Menu:Size(1, -2, 0, 18, OpenInline),
												Position = Menu:Position(0, 1, 0, (19 * (Index - 1)), OpenInline),
												Color = Theme.Colors.C,
												Visible = Tab.Open,
											},
											Dropdown.Holder.Drawings
										)
										--
										local Value = Menu:Create("TextLabel", { NewVector2(6, 5), ValueFrame }, {
											Text = Value,
											Size = Theme.Text.Size,
											Font = Theme.Text.Font,
											Color = Theme.Text.Color,
											OutlineColor = Theme.Text.Outline,
											Position = Menu:Position(0, 6, 0, 5, ValueFrame),
											Visible = Tab.Open,
											Transparency = Transp,
											ZIndex = 9999,
										}, Dropdown.Holder.Drawings)
										--
										Dropdown.Holder.Buttons[#Dropdown.Holder.Buttons + 1] = { Value, ValueFrame }
									end
								end
								--
								Menu:LoadImage(OpenGradient, "Gradient")
								--
								Window.CurrentContent.Frame = OpenInline
								Window.CurrentContent.Dropdown = Dropdown
							else
								Dropdown.Open = not Dropdown.Open
								--
								Menu:LoadImage(DropdownImage, "ArrowDown")
								--
								for _, Drawing in next, Dropdown.Holder.Drawings do
									Menu:Remove(Drawing)
								end
								--
								Dropdown.Holder.Drawings = {}
								Dropdown.Holder.Buttons = {}
								Dropdown.Holder.Inline = nil
								--
								Window.CurrentContent.Frame = nil
								Window.CurrentContent.Dropdown = nil
							end
						else
							if Dropdown.Open then
								Dropdown.Open = not Dropdown.Open
								--
								Menu:LoadImage(DropdownImage, "ArrowDown")
								--
								for _, Drawing in next, Dropdown.Holder.Drawings do
									Menu:Remove(Drawing)
								end
								--
								Dropdown.Holder.Drawings = {}
								Dropdown.Holder.Buttons = {}
								Dropdown.Holder.Inline = nil
								--
								Window.CurrentContent.Frame = nil
								Window.CurrentContent.Dropdown = nil
							end
						end
					elseif Input.UserInputType == Enum.UserInputType.MouseButton1 and Dropdown.Open then
						Dropdown.Open = not Dropdown.Open
						--
						Menu:LoadImage(DropdownImage, "ArrowDown")
						--
						for _, Drawing in next, Dropdown.Holder.Drawings do
							Menu:Remove(Drawing)
						end
						--
						Dropdown.Holder.Drawings = {}
						Dropdown.Holder.Buttons = {}
						Dropdown.Holder.Inline = nil
						--
						Window.CurrentContent.Frame = nil
						Window.CurrentContent.Dropdown = nil
					end
				end
				--
				if Flag and tostring(Flag) ~= "" and tostring(Flag) ~= " " and not Flags[tostring(Flag)] then
					Flags[tostring(Flag)] = Dropdown
				end
				--
				Section.CurrentAxis = Section.CurrentAxis + 18 + 4
				Section:Update()
				--
				return Dropdown
			end
			--
			function Menu.Sections:Label(Info)
				-- Info
				local Info = Info or {}
				local Name = Info.name or Info.Name or Info.Text or Info.text or "New Label"
				local Middle = Info.middle or Info.Middle or Info.center or Info.Center or false
				local Flag = Info.flag or Info.Flag or nil

				local Window = self.Window
				local Tab = self.Tab
				local Section = self

				local Label = { Axis = Section.CurrentAxis }

				do -- Drawings
					local Text = Menu:Create(
						"TextLabel",
						{
							NewVector2(Middle and (Section.SectionOutline.Size.X / 2) or 10, Label.Axis),
							Section.SectionOutline,
						},
						{
							Text = Name,
							Size = Theme.Text.Size,
							Font = Theme.Text.Font,
							Color = Theme.Text.Color,
							OutlineColor = Theme.Text.Outline,
							Center = Middle,
							Position = Menu:Position(
								Middle and 0.5 or 0,
								Middle and 0 or 4,
								0,
								0,
								Section.SectionOutline
							),
							Visible = Tab.Open,
						},
						Section.VisibleContent
					)
					Label["Text"] = Text
				end

				if Flag and tostring(Flag) ~= "" and tostring(Flag) ~= " " and not Flags[tostring(Flag)] then
					Flags[tostring(Flag)] = Label
				end

				Section.CurrentAxis = Section.CurrentAxis + Label["Text"].TextBounds.Y + 4

				return Label
			end
		end

		-- // Notifications
		LPH_NO_VIRTUALIZE(function()
			do
				function Monolith:Notify(Type, Message, Time)
					local Note = { Drawings = {} }
					--
					local TextBounds = Menu:GetTextBounds(Message, Theme.Text.Size, Theme.Text.Font)
					local Outline = Menu:Create(
						"Frame",
						{ NewVector2((Monolith.ScreenSize.X / 2), (Monolith.ScreenSize.Y / 2)) },
						{
							Position = Menu:Position(
								0,
								(Monolith.ScreenSize.X / 2) - (TextBounds.X / 2) - 35,
								0.7,
								(#Monolith.Notes * 19 * 1.4)
							),
							Size = Menu:Size(0, TextBounds.X + 35, 0, TextBounds.Y + 6),
							Color = Theme.Colors.A,
							Hidden = true,
							Visible = true,
							Transparency = 0,
						},
						Note.Drawings
					)
					--
					local Inline = Menu:Create("Frame", { NewVector2(1, 1), Outline }, {
						Position = Menu:Position(0, 1, 0, 1, Outline),
						Size = Menu:Size(1, -2, 1, -2, Outline),
						Color = Theme.Colors.B,
						Hidden = true,
						Transparency = 0,
					}, Note.Drawings)
					--
					local NoteGradient = Menu:Create("Image", { NewVector2(1, 1), Outline }, {
						Position = Menu:Position(0, 1, 0, 1, Outline),
						Size = Menu:Size(1, -2, 1, -2, Outline),
						Transparency = 0,
						Hidden = true,
					}, Note.Drawings)
					--
					Menu:LoadImage(NoteGradient, "Gradient")
					--
					local NoteLogo = Menu:Create("Image", { NewVector2(2, -1), Outline }, {
						Position = Menu:Position(0, 2, 0, -1, Outline),
						Size = Menu:Size(0, 23, 0, 23, Outline),
						Hidden = true,
						Transparency = 0,
					}, Note.Drawings)
					Menu:LoadImage(NoteLogo, Type)
					--
					local NoteText = Menu:Create("TextLabel", { NewVector2(29, 4), Outline }, {
						Position = Menu:Position(0, 29, 0, 4, Outline),
						Text = Message,
						OutlineColor = Theme.Text.Outline,
						Color = Theme.Text.Color,
						Size = Theme.Text.Size,
						Font = Theme.Text.Font,
						Hidden = true,
						Center = false,
						Transparency = 0,
					}, Note.Drawings)
					--
					Monolith.Notes[#Monolith.Notes + 1] = Note
					--
					function Note:Fade(Bool)
						for Index, Value in pairs(Note.Drawings) do
							Menu:Lerp(Value, { Transparency = Bool and 1 or 0 }, 0.25)
						end
					end
					--
					function Note:Remove()
						for Index, CurNote in pairs(Monolith.Notes) do
							if CurNote == Note then
								Monolith.Notes[Index] = nil
							end
						end
						--
						for Index, Drawing in pairs(Note.Drawings) do
							Drawing:Remove()
						end
						--
						Note = nil
					end
					--
					Note:Fade(true)
					Delay(Time, function()
						Note:Fade(false)
						Wait(0.25)
						Note:Remove()
					end)
				end
			end
		end)()
		--

		function Monolith:Unload()
			Monolith:CutConnections(Monolith.Connections)
			--
			Wrap(function()
				Menu.Window:Fade(false)
			end)()
			--
			Wait(0.25)
			Menu.Window:Unload()
			table.clear(self)
		end

