local getclosest = function(fov, mode)
	local CVars = {
		AimbotTarget = { Player = nil, Character = nil, TargetPart = nil, ScreenDistance = math.huge },
		SilentTarget = { Player = nil, Character = nil, TargetPart = nil, ScreenDistance = math.huge },
	}
	for id, gash in ET.Cache do
		if not id or not id.Character then
			continue
		end
		local cache = id.Character
		local goal = cache:FindFirstChild("HumanoidRootPart")

		if not goal or not cache:FindFirstChild("Humanoid") or cache.Humanoid.Health <= 0 then
			continue
		end

		goal = goal.Position
		local screenpos, onscreen = W2VP(Cam, goal)
		if not onscreen then
			continue
		end

		screenpos = Vec2(screenpos.X, screenpos.Y)
		local screendistance = (UINPUT:GetMouseLocation() - screenpos).Magnitude

		local isvisible
		-- silent aim

		if screendistance > fov then
			continue
		end

		if mode == "silent" then
			if Menu.Flags["Silent"].Current and screendistance < SVars.SilentTarget.ScreenDistance then
				CVars.SilentTarget.Character = cache
				CVars.SilentTarget.Player = id
				CVars.SilentTarget.TargetPart = cache:GetChildren()["HumanoidRootPart"]
				CVars.SilentTarget.ScreenDistance = screendistance
			end
		else
			if screendistance < SVars.AimbotTarget.ScreenDistance then
				CVars.AimbotTarget.Character = cache
				CVars.AimbotTarget.Player = id
				CVars.AimbotTarget.TargetPart = cache:GetChildren()["HumanoidRootPart"]
				CVars.AimbotTarget.ScreenDistance = screendistance
			end
		end
	end
	if mode == "silent" then
		if CVars.SilentTarget.Player then
			SVars.SilentTarget = CVars.SilentTarget
			return
		end
		SVars.SilentTarget = NVars.SilentTarget
	else
		if CVars.AimbotTarget.Player then
			SVars.AimbotTarget = CVars.AimbotTarget
			return
		end
		SVars.AimbotTarget = NVars.AimbotTarget
	end
end
