local function SolveBox(Torso)
	local vTop = Torso.Position
	local vBottom = Torso.Position

	local top, topIsRendered = Cam:WorldToViewportPoint(vTop)
	local bottom, bottomIsRendered = Cam:WorldToViewportPoint(vBottom)

	local _width = math.max(math.floor(math.abs(top.x - bottom.x)), 3)
	local _height = math.max(math.floor(math.max(math.abs(bottom.y - top.y), _width / 2)), 3)
	local boxSize = Vector2.new(1, 10)
	local boxPosition = Vector2.new(top.x, math.floor(math.min(top.y, bottom.y)))

	return boxPosition, boxSize, (topIsRendered or bottomIsRendered)
end

do -- Utility
	UT.Functions = {}

	function UT.Functions:RandomChance(percentage)
		value = math.max(0, math.min(value, 100))
		local random_number = math.random(0, 99)
		return random_number < value
	end

	function UT.Functions:SetupChardata(player)
		local CharData = {
			IsAlive = false,
			Moving = false,
			Health = 0,
			Position = Vec3(),
		}

		if not PT[player] then
			PT[player] = CharData
		end
	end

	function UT.Functions:UpdateChardata(player)
		if not PT[player] then
			UT.Functions:SetupChardata(player)
		end

		local ChardataStore = PT[player]

		if player.Character then
			ChardataStore.IsAlive = true
		else
			ChardataStore.IsAlive = false
		end

		if player.Character:FindFirstChild("Humanoid") then
			local Humanoid = player.Character:FindFirstChild("Humanoid")
			ChardataStore.Health = Humanoid.Health
		else
			ChardataStore.Health = 0
		end

		if player.Character:FindFirstChild("HumanoidRootPart") then
			local hrp = player.Character:FindFirstChild("HumanoidRootPart")

			ChardataStore.Position = hrp.CFrame.P
		else
			ChardataStore.Position = Vec3()
		end
	end

	function UT.Functions:FloorVector(vec)
		return Vec3(M2F(vec.X), M2F(vec.Y), M2F(vec.Z))
	end

	function UT.Functions:FloorVector2(one, two)
		return Vec2(M2F(one), M2F(two))
	end

	function UT.Functions:TableToRGB(table)
		return Color3.fromRGB(table[1], table[2], table[3])
	end

	function UT.Functions:TableToNewRGB(table)
		return Color3.new(table[1], table[2], table[3])
	end

	function UT.Functions:IsPositionVisible(origin, to)
		local params = RaycastParams.new()
		params.FilterDescendantsInstances =
			{ game.Players.LocalPlayer.Character, target, ignore ~= nil and unpack(ignore) }

		local direction = (origin - to)
		return (not workspace:Raycast(origin, direction, params))
	end

	function UT.Functions:IsTeammate(player)
		if player.Character and player.Character:FindFirstChild("NameTag") then
			local chilren = player.Character:FindFirstChild("NameTag"):GetChildren()

			if chilren[1] then
				return tostring(chilren[1].TextColor):find("Cyan")
			end
		end
	end

	function UT.Functions:GetPlayerScan(player, character, scans)
		local ScanStatus = { Visible = false, Teammate = false }

		if table.find(scans, "Visible") then
			if UT.Functions:IsPositionVisible(Cam.CFrame.p, character.HumanoidRootPart.CFrame.p) then
				ScanStatus.Visible = true
			end
		end

		if table.find(scans, "Team") then
			if UT.Functions:IsTeammate(player) then
				ScanStatus.Teammate = false
			end
		end

		return ScanStatus
	end
end

do -- esp
	ET.Functions = {}
	ET.Players = {}

	function ET.Functions:Create(player)
		-- local Highlight = Instance.new("Highlight", game)
		if player == nil then
			return
		end
		if ET.Cache[player] then
			return
		end

		ET.Cache[player] = {
			-- Box
			B2 = Drawing.new("Quad"),
			B3 = Drawing.new("Quad"),
			B1 = Drawing.new("Quad"),
			-- Health
			H1 = Drawing.new("Quad"),
			H2 = Drawing.new("Quad"),

			N1 = Drawing.new("Text"),
			N2 = Drawing.new("Text"),
		}

		return ET.Cache[player]
	end

	function ET.Functions:Remove(cache)
		for _, SELECTED in cache do
			SELECTED.Visible = false

			SELECTED:Destroy()

			cache[_] = nil
		end

		cache = nil
	end

	function ET.Functions:SRemove(cache)
		for _, SELECTED in cache do
			SELECTED.Visible = false
		end
	end

	function ET.Functions:AddPlayer(player)
		if not ET.Cache[player] then
			ET.Cache[player] = ET.Functions:Create()
		end
		return ET.Cache[player]
	end

	function ET.Functions:Update(player)
		if not ET.Cache[player] then
			return
		end

		local cash = ET.Cache[player]

		if player.Parent ~= game:GetService("Players") then
			ET.Functions:Remove(cash)
			return
		end

		if not cash then
			return
		end

		if not Menu.Flags["Enemy "].Current then
			ET.Functions:SRemove(cash)
			return
		end

		if
			not game.Players.LocalPlayer.Character
			or not game.Players.LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
		then
			ET.Functions:SRemove(cash)
			return
		end

		if not player.Character then
			ET.Functions:SRemove(cash)
			return
		end

		if not player.Character:FindFirstChild("HumanoidRootPart") then
			ET.Functions:SRemove(cash)
			return
		end

		if not player.Character:FindFirstChild("Humanoid") then
			ET.Functions:SRemove(cash)
			return
		end

		local PLRHRP = game.Players.LocalPlayer.Character:FindFirstChild("HumanoidRootPart").Position
			or Vector3.new(0, 0, 0)

		local DistanceN = (player.Character.HumanoidRootPart.Position - PLRHRP).Magnitude

		local hum = player.Character:FindFirstChild("Humanoid")
		local healthpercentage = (hum.Health / hum.MaxHealth)

		local P1, P2 = SolveBox(player.Character.HumanoidRootPart)

		local main_cpos = player.Character.HumanoidRootPart.CFrame

		local main_cpos_b = player.Character.HumanoidRootPart.CFrame * CFrame.new(Vec3(1.05, 0, 0))

		local FV2 = UT.Functions.FloorVector2
		local FV = UT.Functions

		local Quad = ET.Cache[player].B1
		local QuadOutline = ET.Cache[player].B2
		local QuadFill = ET.Cache[player].B3

		local Health = ET.Cache[player].H1
		local HealthFill = ET.Cache[player].H2

		local Name = ET.Cache[player].N1
		local Distance = ET.Cache[player].N2

		local BoxSizeEditorX = (2 / Menu.Flags["Box Size Scale X"].Current)
		local BoxSizeEditorY = (2 / Menu.Flags["Box Size Scale Y"].Current)

		local HealthSizeEditorX = (8 / Menu.Flags["Health Size Scale X"].Current)
		local HealthSizeEditorY = (2 / Menu.Flags["Health Size Scale Y"].Current)

		local function GetFootPos()
			local character = player.Character
			local humanoidRootPart = character:FindFirstChild("HumanoidRootPart")
			local humanoid = character:FindFirstChildOfClass("Humanoid")

			if humanoidRootPart and humanoid then
				local rootCFrame = humanoidRootPart.CFrame
				local rootOffset = Vec3(0, 0.5, 0) * humanoid.HipHeight
				local feetOffset = Vec3(0, -0.5, 0) * humanoid.HipHeight
				local feetPosition = CFrame.new(rootCFrame * feetOffset)
				return feetPosition
			end
		end

		local function GetPosInfo()
			local size = CFrame.new(Vec3(2, 5, 0))
			local shift = CFrame.new(Vec3(0, -0.5, 0))
			local poo = CFrame.new(main_cpos.p, Cam.CFrame.p)
			local locs = {
				TopMiddle = main_cpos * shift * CFrame.new(0, size.Y / 2, 0),
				BottomMiddle = main_cpos * shift * CFrame.new(0, -size.Y / 2, 0),
				Torso = main_cpos,
			}

			local TopMiddle, Vis1 = W2VP(Cam, locs.TopMiddle.p)
			local BottomMiddle, Vis2 = W2VP(Cam, locs.BottomMiddle.p)

			return UT.Functions:FloorVector(TopMiddle), UT.Functions:FloorVector(BottomMiddle), (Vis1 or Vis2)
		end

		local t1, b2, Active = GetPosInfo()

		-- Section:Toggle({Name = "Draw Enemies", Flag = "Enemy ", Default = false})
		-- Section:Slider({Name = "Draw Range", Flag = "Enemy Max Distance", Length = 0.46, Minimum = 100, Default = 800, Maximum = 2500, Decimals = 1})
		-- Section:Toggle({Name = "Draw Name ESP", Flag = "Enemy Name", Default = false})
		-- Section:Toggle({Name = "Draw Box ESP", Flag = "Enemy Box", Default = false})
		-- Section:Toggle({Name = "Draw Filled Box", Flag = "Enemy Box Fill", Default = false})
		-- Section:Slider({Name = "Filled Box Opacity", Flag = "Enemy Box Fill Opacity", Minimum = 0.1, Default = 0.2, Maximum = 0.5, Decimals = 0.05})
		-- Section:Toggle({Name = "Draw Health Bar", Flag = "Enemy Health Bar", Default = false})
		-- Section:Toggle({Name = "Draw Weapon ESP", Flag = "Enemy Weapon", Default = false})
		-- Section:Toggle({Name = "Draw Distance ESP", Flag = "Enemy Distance", Default = false})
		-- --Section:Toggle({Name = "Chams", Flag = "Enemy Chams", Default = false})
		-- --Section:Label({Text = "Chams are not affected by the ESP.", Middle = true})
		-- Section:Toggle({Name = "Draw OOF Arrows", Flag = "Enemy Arrow", Default = false})
		-- Section:Slider({Name = "OOF Size", Flag = "Enemy Arrow Size", Minimum = 5, Default = 16, Maximum = 25})
		-- Section:Slider({Name = "OOF Position", Flag = "Enemy Arrow Position", Length = 0.40, Minimum = 0.05, Default = 0.01, Maximum = 0.5, Decimals = 0.01})
		-- Section:Slider({Name = "OOF Range", Flag = "Enemy Arrow Distance", Length = 0.46, Minimum = 100, Default = 600, Maximum = 1200, Decimals = 1})
		-- Section:Dropdown({Name = "OOF Types", Flag = "Enemy Arrow Types", Length = 0.58, Multi = true, Min = 0, Default = {"Name", "Health Bar"}, Options = {"Name", "Health Bar", "Weapon", "Distance", "Status"}})
		-- Section:Toggle({Name = "Draw Status", Flag = "Enemy Status", Default = false})

		local size = CFrame.new(Vec3(2, 5, 0))
		local HealthSize = CFrame.new(Vec3(0.04, 5, 0))

		local shift = CFrame.new(Vec3(0, -0.5, 0))
		local shift2 = CFrame.new(Vec3(0, -3, 0))

		local main_cpos_p = main_cpos.p
		local main_cpos_q = main_cpos.p - Vec3(2, 0, 0)

		local BoxSizeEditorY_inverse = 1 / BoxSizeEditorY
		local BoxSizeEditorX_inverse = 1 / BoxSizeEditorX

		local Misc2_Y_Offset = (HealthSize.Y * 2 / BoxSizeEditorY) * healthpercentage
		local Misc1_Y_Offset = (HealthSize.Y * 2 / BoxSizeEditorY)

		local locs = {
			TopLeft = main_cpos
				* shift
				* CFrame.new(size.X * BoxSizeEditorX_inverse, size.Y * BoxSizeEditorY_inverse, 0),
			TopRight = main_cpos
				* shift
				* CFrame.new(-size.X * BoxSizeEditorX_inverse, size.Y * BoxSizeEditorY_inverse, 0),
			BottomLeft = main_cpos
				* shift
				* CFrame.new(size.X * BoxSizeEditorX_inverse, -size.Y * BoxSizeEditorY_inverse, 0),
			BottomRight = main_cpos
				* shift
				* CFrame.new(-size.X * BoxSizeEditorX_inverse, -size.Y * BoxSizeEditorY_inverse, 0),

			Torso = main_cpos,

			Misc1 = main_cpos_b * shift2 * CFrame.new(HealthSize.X * BoxSizeEditorX_inverse, Misc1_Y_Offset, 0),
			Misc6 = main_cpos_b * shift2 * CFrame.new(-HealthSize.X * BoxSizeEditorX_inverse, Misc1_Y_Offset, 0),

			Misc2 = main_cpos_b * shift2 * CFrame.new(HealthSize.X * BoxSizeEditorX_inverse, Misc2_Y_Offset, 0),
			Misc3 = main_cpos_b * shift2 * CFrame.new(-HealthSize.X * BoxSizeEditorX_inverse, Misc2_Y_Offset, 0),

			Misc4 = main_cpos_b
				* shift
				* CFrame.new(HealthSize.X * BoxSizeEditorX_inverse, -HealthSize.Y * BoxSizeEditorY_inverse, 0),
			Misc5 = main_cpos_b
				* shift
				* CFrame.new(-HealthSize.X * BoxSizeEditorX_inverse, -HealthSize.Y * BoxSizeEditorY_inverse, 0),
		}

		local function GetQuadInfo()
			local TopLeft = W2VP(Cam, locs.TopLeft.p)
			local TopRight = W2VP(Cam, locs.TopRight.p)
			local BottomLeft = W2VP(Cam, locs.BottomLeft.p)
			local BottomRight = W2VP(Cam, locs.BottomRight.p)

			-- Misc1 and 6 add up
			-- 1 is left and 6 is right

			local Middle1, Rendered = W2VP(Cam, locs.Misc1.p)

			local Middle2 = W2VP(Cam, locs.Misc2.p)

			local Middle3 = W2VP(Cam, locs.Misc3.p)

			local Middle4 = W2VP(Cam, locs.Misc4.p)

			local Middle5 = W2VP(Cam, locs.Misc5.p)

			local Middle6 = W2VP(Cam, locs.Misc6.p)

			return TopLeft,
				TopRight,
				BottomLeft,
				BottomRight,
				Rendered,
				Middle1,
				Middle2,
				Middle3,
				Middle4,
				Middle5,
				Middle6
		end

		local TopLeft, TopRight, BottomLeft, BottomRight, Rendered, Middle1, Middle2, Middle3, Middle4, Middle5, Middle6 =
			GetQuadInfo()

		do -- quads
			QuadFill.Visible = Rendered and Menu.Flags["Enemy Box Fill"].Current
			Quad.Visible = Rendered and Menu.Flags["Enemy Box"].Current
			QuadOutline.Visible = Rendered and Menu.Flags["Enemy Box"].Current

			if Rendered then
				Quad.PointA = FV2(FV, TopRight.X, TopRight.Y)
				Quad.PointB = FV2(FV, TopLeft.X, TopLeft.Y)
				Quad.PointC = FV2(FV, BottomLeft.X, BottomLeft.Y)
				Quad.PointD = FV2(FV, BottomRight.X, BottomRight.Y)
				Quad.Color = Color3.new(1, 1, 1)
			else
				Quad.Visible = false
			end

			if Rendered then
				QuadOutline.PointA = FV2(FV, TopRight.X, TopRight.Y)
				QuadOutline.PointB = FV2(FV, TopLeft.X, TopLeft.Y)
				QuadOutline.PointC = FV2(FV, BottomLeft.X, BottomLeft.Y)
				QuadOutline.PointD = FV2(FV, BottomRight.X, BottomRight.Y)
				QuadOutline.Color = Color3.new(0, 0, 0)
				QuadOutline.Thickness = 3
			else
				QuadOutline.Visible = false
			end

			if Rendered then
				QuadFill.PointA = FV2(FV, TopRight.X, TopRight.Y)
				QuadFill.PointB = FV2(FV, TopLeft.X, TopLeft.Y)
				QuadFill.PointC = FV2(FV, BottomLeft.X, BottomLeft.Y)
				QuadFill.PointD = FV2(FV, BottomRight.X, BottomRight.Y)
				QuadFill.Color = Color3.new(0, 0, 0)
				QuadFill.Transparency = Menu.Flags["Enemy Box Fill Opacity"].Current
				QuadFill.Filled = true
			else
				QuadFill.Visible = false
			end
		end

		do -- Health bars
			HealthFill.Visible = Rendered and Menu.Flags["Enemy Health Bar"].Current
			Health.Visible = Rendered and Menu.Flags["Enemy Health Bar"].Current

			if Rendered then
				HealthFill.PointA = Vec2(Middle3.X, Middle3.Y)
				HealthFill.PointB = Vec2(Middle2.X, Middle2.Y)
				HealthFill.PointC = Vec2(Middle4.X, Middle4.Y)
				HealthFill.PointD = Vec2(Middle5.X, Middle5.Y)
				HealthFill.Color = Color3.new(0, 1, 0)
				HealthFill.Filled = true
			end

			if Rendered then
				Health.PointA = Vec2(Middle6.X + 1, Middle6.Y + 1)
				Health.PointB = Vec2(Middle1.X - 1, Middle1.Y - 1)
				Health.PointC = Vec2(Middle4.X - 1, Middle4.Y - 1)
				Health.PointD = Vec2(Middle5.X + 1, Middle5.Y + 1)
				Health.Color = Color3.new(0, 0, 0)
				Health.Thickness = 4
				Health.Filled = true
			end
		end

		do -- Names
			local TextBounds = Name.TextBounds
			Name.Text = player.DisplayName
			Name.Position = Vec2(t1.X, t1.Y - TextBounds.Y - 1)
			Name.Visible = Active and Menu.Flags["Enemy Name"].Current
			Name.Size = 11

			Name.Color = Color3.new(1, 1, 1)
			Name.Outline = true
			Name.Font = Minecrafia
			Name.Center = true
		end

		do -- Distance
			local t1 = GetPosInfo()
			local TextBounds = Name.TextBounds
			Distance.Text = math.floor(DistanceN) .. " M"
			Distance.Position = Vec2(b2.X, b2.Y)
			Distance.Visible = Active and Menu.Flags["Enemy Distance"].Current
			Distance.Size = 11

			Distance.Color = Color3.new(1, 1, 1)
			Distance.Outline = true
			Distance.Font = Minecrafia
			Distance.Center = true
		end
	end

	ET.Functions.Loop = function()
		for _, Selected in game:GetService("Players"):GetChildren() do
			if Selected ~= LOCAL then
				ET.Functions:Create(Selected)
			end
		end

		for Player, Selected in ET.Cache do
			ET.Functions:Update(Player)
		end
	end

	table.insert(UT.Loops, ET.Functions.Loop)
end

do
