--SECTION - Drawing Updater
function CDrawings:Update()
	if Menu.Flags["Assist"].Current then
		local Circle = CDrawings.Aimbot.FovCircle1
		local Outline = CDrawings.Aimbot.FovCircle2
		local MousePosition = Cam.ViewportSize / 2
		if Menu.Flags["Assist Follow"] then
			MousePosition = UINPUT:GetMouseLocation()
		end

		Circle.Radius = Menu.Flags["Assist FOV Degrees"].Current
		Circle.Visible = Menu.Flags["Assist Draw"].Current
		Circle.Color = Menu.Flags["Assist Color"]:Get().Color
		Circle.Transparency = ABS(Menu.Flags["Assist Color"]:Get().Transparency - 1)
		Circle.Position = MousePosition

		Outline.Radius = Menu.Flags["Assist FOV Degrees"].Current
		Outline.Visible = Menu.Flags["Assist Draw"].Current
		Outline.Color = Menu.Flags["Assist Color2"]:Get().Color
		Outline.Transparency = ABS(Menu.Flags["Assist Color2"]:Get().Transparency - 1)
		Outline.Position = MousePosition
		Outline.Thickness = 2
	else
		local Circle = CDrawings.Aimbot.FovCircle1
		local Outline = CDrawings.Aimbot.FovCircle2

		Circle.Visible = false
		Outline.Visible = false
	end

	if Menu.Flags["Silent"].Current then
		local Circle = CDrawings.SilentAim.FovCircle1
		local Outline = CDrawings.SilentAim.FovCircle2
		local MousePosition = Cam.ViewportSize / 2
		if Menu.Flags["Silent Follow"] then
			MousePosition = UINPUT:GetMouseLocation()
		end

		Circle.Radius = Menu.Flags["Silent FOV Degrees"].Current
		Circle.Visible = Menu.Flags["Silent Draw"].Current
		Circle.Color = Menu.Flags["Silent Color"]:Get().Color
		Circle.Transparency = ABS(Menu.Flags["Silent Color"]:Get().Transparency - 1)
		Circle.Position = MousePosition

		Outline.Radius = Menu.Flags["Silent FOV Degrees"].Current
		Outline.Visible = Menu.Flags["Silent Draw"].Current
		Outline.Color = Menu.Flags["Silent Color2"]:Get().Color
		Outline.Transparency = ABS(Menu.Flags["Silent Color2"]:Get().Transparency - 1)
		Outline.Position = MousePosition
		Outline.Thickness = 2
	else
		local Circle = CDrawings.SilentAim.FovCircle1
		local Outline = CDrawings.SilentAim.FovCircle2

		Circle.Visible = false
		Outline.Visible = false
	end

	do
		local TDISPLAY = CDrawings.SilentAim.TargetDisplay
		if Workspace:FindFirstChild("VFX") and Workspace.VFX:FindFirstChild("VMs") then
			pcall(function()
				local Viewmodels = Workspace.VFX.VMs:GetChildren()

				if #Viewmodels >= 1 then
					local VM = Viewmodels[1]

					local Barrel = VM.Weapon:FindFirstChild("FlashPart")
					if not Barrel then
						return
					end

					local GRegisty = GM.Functions:GetGunRegisty(VM.Name)
					if not GRegisty then
						return
					end

					local VMControl = LOCAL.Character:FindFirstChild("ViewmodelController")
					if not VMControl then
						return
					end

					local Display_Position, Visible = W2VP(Cam, Barrel.CFrame.p)

					TDISPLAY.Position = Vec2(Display_Position.X, Display_Position.Y)

					if VMControl:GetAttribute("Ammo") then
						TDISPLAY.Text = "Current Ammo: " .. VMControl:GetAttribute("Ammo") .. ""
					end

					TDISPLAY.Center = true
					TDISPLAY.Visible = true
					TDISPLAY.Color = Color3.new(1, 1, 1)
					TDISPLAY.Font = Minecrafia
					TDISPLAY.Outline = true
					TDISPLAY.Size = 11
				else
					TDISPLAY.Visible = false
				end
			end)
		end
	end
end

table.insert(UT.Loops, CDrawings.Update)
