--SECTION - Aimbot Loops
function Update_Aimtarget()
	getclosest(Menu.Flags["Silent FOV Degrees"]:Get(), "silent")

	do -- Sticky Targeting
		if
			not SVars.AimbotTarget.Player
			and Menu.Flags["Assist Sticky"].Current
			and Menu.Flags["Assist"].Current
			and Menu.Flags["Assist Key"].Active
		then
			getclosest(Menu.Flags["Assist FOV Degrees"]:Get(), "aimbot")
			return
		elseif
			SVars.AimbotTarget.Player
			and Menu.Flags["Assist Sticky"].Current
			and Menu.Flags["Assist"].Current
			and Menu.Flags["Assist Key"].Active == false
		then
			SVars.AimbotTarget = NVars.AimbotTarget
			return
		end

		if Menu.Flags["Assist Sticky"].Current then
			return
		end
	end

	getclosest(Menu.Flags["Assist FOV Degrees"]:Get(), "aimbot")
end

function Update_Aimbot()
	if
		(tick() >= Ticks.Tick1 + (Menu.Flags["Assist Stutter"].Current / 1000))
		and SVars.AimbotTarget
		and SVars.AimbotTarget.Player
		and SVars.AimbotTarget.Character
	then
		if Menu.Flags["Assist"].Current and Menu.Flags["Assist Key"].Active then
			local Pos = W2VP(Cam, SVars.AimbotTarget.Character:FindFirstChild("Head").Position)
			local Mouse = UINPUT:GetMouseLocation()

			mousemoverel(
				(Pos.X - Mouse.X) / (Menu.Flags["Assist Smoothing X"].Current / 10),
				(Pos.Y - Mouse.Y) / (Menu.Flags["Assist Smoothing Y"].Current / 10)
			)
		end

		Ticks.Tick1 = tick()
	end
end

table.insert(UT.Loops, Update_Aimtarget)
table.insert(UT.Loops, Update_Aimbot)
